170	bool CheckInputOutDims(const AiInfraMainfoldConstrainedHyperConnectionParamsBase &params)
171	{
172	    constexpr size_t DIM_NUM_1 = 1UL;
173	    constexpr size_t DIM_NUM_2 = 2UL;
174	    constexpr size_t DIM_NUM_3 = 3UL;
175	    constexpr size_t DIM_NUM_4 = 4UL;
176	    
177	    // x可以是3维或4维
178	    auto xDimNum = params.x->GetViewShape().GetDimNum();
179	    if (xDimNum != DIM_NUM_3 && xDimNum != DIM_NUM_4) {
180	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "x tensor dim num must be 3 or 4, but got %zu", xDimNum);
181	        return false;
182	    }
183	    
184	    // phi应该是2维: (n^2+2n, nD)
185	    auto phiDimNum = params.phi->GetViewShape().GetDimNum();
186	    if (phiDimNum != DIM_NUM_2) {
187	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "phi tensor dim num must be 2, but got %zu", phiDimNum);
188	        return false;
189	    }
190	
191	    // alpha应该是1维: (3)
192	    auto alphaDimNum = params.alpha->GetViewShape().GetDimNum();
193	    if (alphaDimNum != DIM_NUM_1) {
194	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "alpha tensor dim num must be 1, but got %zu", alphaDimNum);
195	        return false;
196	    }
197	    
198	    // bias应该是1维: (n^2+2n)
199	    auto biasDimNum = params.bias->GetViewShape().GetDimNum();
200	    if (biasDimNum != DIM_NUM_1) {
201	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "bias tensor dim num must be 1, but got %zu", biasDimNum);
202	        return false;
203	    }
204	
205	    // gamma应该是2维: (n, D)
206	    if (params.gamma != nullptr) {
207	        auto gammaDimNum = params.gamma->GetViewShape().GetDimNum();
208	        if (gammaDimNum != DIM_NUM_2) {
209	            OP_LOGE(ACLNN_ERR_PARAM_INVALID, "gamma tensor dim num must be 2, but got %zu", gammaDimNum);
210	            return false;
211	        }
212	    }
213	    
214	    return true;
215	}
216	
217	bool CheckInputOutShape(const AiInfraMainfoldConstrainedHyperConnectionParamsBase &params)
218	{
219	    auto xShape = params.x->GetViewShape();
220	    auto phiShape = params.phi->GetViewShape();
221	    auto alphaShape = params.alpha->GetViewShape();
222	    auto biasShape = params.bias->GetViewShape();
223	
224	    auto xDimNum = xShape.GetDimNum();
225	    
226	    // alpha的shape必须是(3)
227	    if (alphaShape.GetDim(0) != 3) {
228	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "alpha tensor shape must be (3), but got (%ld)", alphaShape.GetDim(0));
229	        return false;
230	    }
231	    
232	    // 从x的shape推导n和D
233	    int64_t n = 0;  // numsResidual
234	    int64_t d = 0;  // dimen
235	    int64_t nD = 0; // n * D
236	    
237	    if (xDimNum == 4) { // 4 : 当x的维度为4维
238	        // BSND格式: (B, S, N, D)
239	        n = xShape.GetDim(2);  // 2: 获取N维度
240	        d = xShape.GetDim(3);  // 3: 获取D维度
241	        nD = n * d;
242	    } else if (xDimNum == 3) { // 3 : 当x的维度为3维
243	        // TND格式: (T, N, D)
244	        n = xShape.GetDim(1);  // 1: 获取N维度
245	        d = xShape.GetDim(2);  // 2: 获取D维度
246	        nD = n * d;
247	    } else {
248	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "x tensor dim num must be 3 or 4, but got %zu", xDimNum);
249	        return false;
250	    }
251	    
252	    if (n <= 0 || d <= 0) {
253	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "Invalid x tensor shape: n=%ld, d=%ld", n, d);
254	        return false;
255	    }
256	    
257	    int64_t n2_plus_2n = n * n + 2 * n;  // n^2 + 2n
258	
259	    // phi的shape应该是(n^2+2n, nD)
260	    if (phiShape.GetDim(0) != n2_plus_2n) {
261	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "phi tensor first dim must be n^2+2n=%ld, but got %ld", n2_plus_2n,
262	                phiShape.GetDim(0));
263	        return false;
264	    }
265	    if (phiShape.GetDim(1) != nD) {
266	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "phi tensor second dim must be nD=%ld, but got %ld", nD, phiShape.GetDim(1));
267	        return false;
268	    }
269	    // bias的shape应该是(n^2+2n)
270	    if (biasShape.GetDim(0) != n2_plus_2n) {
271	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "bias tensor dim must be n^2+2n=%ld, but got %ld", n2_plus_2n,
272	                biasShape.GetDim(0));
273	        return false;
274	    }
275	    // gamma的shape应该是(n, D)
276	    if (params.gamma != nullptr) {
277	        auto gammaShape = params.gamma->GetViewShape();
278	        if (gammaShape.GetDim(0) != n) {
279	            OP_LOGE(ACLNN_ERR_PARAM_INVALID, "gamma tensor first dim must be n=%ld, but got %ld", n,
280	                    gammaShape.GetDim(0));
281	            return false;
282	        }
283	        if (gammaShape.GetDim(1) != d) {
284	            OP_LOGE(ACLNN_ERR_PARAM_INVALID, "gamma tensor second dim must be D=%ld, but got %ld", d,
285	                    gammaShape.GetDim(1));
286	            return false;
287	        }
288	    }
289	
290	    return true;
291	}
292	
293	bool CheckDtypeValid(const AiInfraMainfoldConstrainedHyperConnectionParamsBase &params)
294	{
295	    // x支持BF16或FP16
296	    const std::initializer_list<DataType> X_SUPPORT_DTYPE_LIST = {DataType::DT_BF16, DataType::DT_FLOAT16};
297	    
298	    auto xDtype = params.x->GetDataType();
299	    bool xDtypeValid = false;
300	    for (const auto &dtype : X_SUPPORT_DTYPE_LIST) {
301	        if (xDtype == dtype) {
302	            xDtypeValid = true;
303	            break;
304	        }
305	    }
306	    if (!xDtypeValid) {
307	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "x tensor dtype must be BF16 or FP16");
308	        return false;
309	    }
310	    
311	    // phi, gamma, alpha, bias都必须是FP32
312	    if (params.phi->GetDataType() != DataType::DT_FLOAT) {
313	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "phi tensor dtype must be FP32");
314	        return false;
315	    }
316	    if (params.alpha->GetDataType() != DataType::DT_FLOAT) {
317	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "alpha tensor dtype must be FP32");
318	        return false;
319	    }
320	    if (params.bias->GetDataType() != DataType::DT_FLOAT) {
321	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "bias tensor dtype must be FP32");
322	        return false;
323	    }
324	    if (params.gamma != nullptr) {
325	        if (params.gamma->GetDataType() != DataType::DT_FLOAT) {
326	            OP_LOGE(ACLNN_ERR_PARAM_INVALID, "gamma tensor dtype must be FP32");
327	            return false;
328	        }
329	    }
330	    
331	    return true;
332	}
333	
334	static bool IsPrivateFormat(ge::Format format)
335	{
336	    if (format == ge::FORMAT_NC1HWC0 || format == ge::FORMAT_FRACTAL_Z || format == ge::FORMAT_NDC1HWC0 ||
337	        format == ge::FORMAT_FRACTAL_Z_3D || format == ge::FORMAT_FRACTAL_NZ || format == ge::FORMAT_NC1HWC0_C04) {
338	        return true;
339	    }
340	
341	    return false;
342	}
343	
344	bool CheckFormat(const AiInfraMainfoldConstrainedHyperConnectionParamsBase &params)
345	{
346	    // 检查所有输入tensor的format必须是ND格式
347	    if (IsPrivateFormat(params.x->GetViewFormat())) {
348	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "x tensor format must be ND");
349	        return false;
350	    }
351	    
352	    if (IsPrivateFormat(params.phi->GetViewFormat())) {
353	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "phi tensor format must be ND");
354	        return false;
355	    }
356	
357	    if (IsPrivateFormat(params.alpha->GetViewFormat())) {
358	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "alpha tensor format must be ND");
359	        return false;
360	    }
361	    
362	    if (IsPrivateFormat(params.bias->GetViewFormat())) {
363	        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "bias tensor format must be ND");
364	        return false;
365	    }
366	
367	    if (params.gamma != nullptr) {
368	        if (IsPrivateFormat(params.gamma->GetViewFormat())) {
369	            OP_LOGE(ACLNN_ERR_PARAM_INVALID, "gamma tensor format must be ND");
370	            return false;
371	        }
372	    }
373	
374	    return true;
375	}
376	
377	aclnnStatus CheckParams(const AiInfraMainfoldConstrainedHyperConnectionParamsBase &params)
378	{
379	    // 1. 检查参数是否为空指针、空tensor
380	    CHECK_RET(CheckNotNull(params), ACLNN_ERR_PARAM_NULLPTR);
381	    CHECK_RET(CheckEmptyTensor(params), ACLNN_ERR_PARAM_INVALID);
382	
383	    // 2. 校验输入、输出参数维度
384	    CHECK_RET(CheckInputOutDims(params), ACLNN_ERR_PARAM_INVALID);
385	
386	    // 3. 校验输入、输出shape参数
387	    CHECK_RET(CheckInputOutShape(params), ACLNN_ERR_PARAM_INVALID);
388	
389	    // 4. 检查输入的数据类型是否在支持的数据类型范围之内
390	    CHECK_RET(CheckDtypeValid(params), ACLNN_ERR_PARAM_INVALID);
391	
392	    // 5. 检查数据形状是否支持
393	    CHECK_RET(CheckFormat(params), ACLNN_ERR_PARAM_INVALID);
394	
395	    return ACLNN_SUCCESS;
396	}
397	
398	aclnnStatus CovertDataContiguous(AiInfraMainfoldConstrainedHyperConnectionParamsBase &params, aclOpExecutor *executor)
399	{
400	    // 将输入tensor转换为连续格式
401	    params.x_contiguous = l0op::Contiguous(params.x, executor);
402	    CHECK_RET(params.x_contiguous != nullptr, ACLNN_ERR_INNER_NULLPTR);
403	    
404	    params.phi_contiguous = l0op::Contiguous(params.phi, executor);
405	    CHECK_RET(params.phi_contiguous != nullptr, ACLNN_ERR_INNER_NULLPTR);
406	
407	    params.alpha_contiguous = l0op::Contiguous(params.alpha, executor);
408	    CHECK_RET(params.alpha_contiguous != nullptr, ACLNN_ERR_INNER_NULLPTR);
409	    
410	    params.bias_contiguous = l0op::Contiguous(params.bias, executor);
411	    CHECK_RET(params.bias_contiguous != nullptr, ACLNN_ERR_INNER_NULLPTR);
412	
413	    if (params.gamma != nullptr) {
414	        params.gamma_contiguous = l0op::Contiguous(params.gamma, executor);
415	        CHECK_RET(params.gamma_contiguous != nullptr, ACLNN_ERR_INNER_NULLPTR);
416	    }
417	    
418	    return ACLNN_SUCCESS;
419	}
420	
421	static aclnnStatus aiInfraMHCPreCommonProcess(AiInfraMainfoldConstrainedHyperConnectionParamsBase &params,
422	                                              aclOpExecutor *executor)
423	{
424	    auto ret = CheckParams(params);
425	    CHECK_RET(ret == ACLNN_SUCCESS, ret);
426	
427	    ret = CovertDataContiguous(params, executor);
428	    CHECK_RET(ret == ACLNN_SUCCESS, ret);
429	
430	    // 使用转换后的连续tensor
431	    auto outParams = l0op::AiInfraManifoldConstrainedHyperConnectionPre(
432	        params.x_contiguous, params.phi_contiguous, params.alpha_contiguous, params.bias_contiguous,
433	        params.gamma_contiguous, params.outFlag, params.normEps, params.hcEps, executor);
434	    CHECK_RET(outParams != std::tuple(nullptr, nullptr, nullptr, nullptr, nullptr, nullptr), ACLNN_ERR_INNER_NULLPTR);
435	
436	    auto out0 = std::get<0>(outParams);
437	    auto ret0 = l0op::ViewCopy(out0, params.outHin, executor);
438	    CHECK_RET(ret0 != nullptr, ACLNN_ERR_INNER_NULLPTR);
439	
440	    auto out1 = std::get<1>(outParams);
441	    auto ret1 = l0op::ViewCopy(out1, params.outHPost, executor);
442	    CHECK_RET(ret1 != nullptr, ACLNN_ERR_INNER_NULLPTR);
443	
444	    auto out2 = std::get<2>(outParams);
445	    auto retView = l0op::ViewCopy(out2, params.outHRes, executor);
446	    CHECK_RET(retView != nullptr, ACLNN_ERR_INNER_NULLPTR);
447	
448	    auto out3 = std::get<3>(outParams);
449	    retView = l0op::ViewCopy(out3, params.outInvRms, executor);
450	    CHECK_RET(retView != nullptr, ACLNN_ERR_INNER_NULLPTR);
451	
452	    auto out4 = std::get<4>(outParams);
453	    retView = l0op::ViewCopy(out4, params.outMmRes, executor);
454	    CHECK_RET(retView != nullptr, ACLNN_ERR_INNER_NULLPTR);
455	
456	    auto out5 = std::get<5>(outParams);
457	    retView = l0op::ViewCopy(out5, params.outHPre, executor);
458	    CHECK_RET(retView != nullptr, ACLNN_ERR_INNER_NULLPTR);
459	
460	    return ACLNN_SUCCESS;
461	}
462	
463	aclnnStatus aclnnAiInfraManifoldConstrainedHyperConnectionPreGetWorkspaceSize(
464	    const aclTensor *x, const aclTensor *phi, const aclTensor *alpha, const aclTensor *bias, const aclTensor *gamma,
465	    int64_t outFlag, double normEps, double hcEps, const aclTensor *outHin, const aclTensor *outHPost,
466	    const aclTensor *outHRes, const aclTensor *outInvRms, const aclTensor *outMmRes, const aclTensor *outHPre,
467	    uint64_t *workspaceSize, aclOpExecutor **executor)
