using namespace op;

#ifdef __cplusplus
extern "C" {
#endif

namespace {

struct AiInfraMainfoldConstrainedHyperConnectionParamsBase {
    const aclTensor *x = nullptr;
    const aclTensor *phi = nullptr;
    const aclTensor *alpha = nullptr;
    const aclTensor *bias = nullptr;
    const aclTensor *gamma = nullptr;
    int64_t outFlag;
    double normEps;
    double hcEps;
    const aclTensor *outHin = nullptr;
    const aclTensor *outHPost = nullptr;
    const aclTensor *outHRes = nullptr;
    const aclTensor *outInvRms = nullptr;
    const aclTensor *outMmRes = nullptr;
    const aclTensor *outHPre = nullptr;

    // 用于存储转换后的连续tensor（在CovertDataContiguous中使用）
    const aclTensor *x_contiguous = nullptr;
    const aclTensor *phi_contiguous = nullptr;
    const aclTensor *alpha_contiguous = nullptr;
    const aclTensor *bias_contiguous = nullptr;
    const aclTensor *gamma_contiguous = nullptr;
};

class AiInfraMainfoldConstrainedHyperConnectionBuilder {
public:
    static AiInfraMainfoldConstrainedHyperConnectionBuilder Create()
    {
        AiInfraMainfoldConstrainedHyperConnectionBuilder obj;

        return obj;
    }

    AiInfraMainfoldConstrainedHyperConnectionBuilder &SetInput(const aclTensor *x, const aclTensor *phi,
                                                               const aclTensor *alpha, const aclTensor *bias,
                                                               const aclTensor *gamma)
    {
        obj_.x = x;
        obj_.phi = phi;
        obj_.alpha = alpha;
        obj_.bias = bias;
        obj_.gamma = gamma;
        return *this;
    }

    AiInfraMainfoldConstrainedHyperConnectionBuilder &SetAttr(int64_t outFlag, double normEps, double hcEps)
    {
        obj_.outFlag = outFlag;
        obj_.normEps = normEps;
        obj_.hcEps = hcEps;
        return *this;
    }

    AiInfraMainfoldConstrainedHyperConnectionBuilder &SetOutput(const aclTensor *outHin, const aclTensor *outHPost,
                                                                const aclTensor *outHRes)
    {
        obj_.outHin = outHin;
        obj_.outHPost = outHPost;
        obj_.outHRes = outHRes;
        return *this;
    }

    AiInfraMainfoldConstrainedHyperConnectionBuilder &
    SetOptionalOutput(const aclTensor *outInvRms, const aclTensor *outMmRes, const aclTensor *outHPre)
    {
        obj_.outInvRms = outInvRms;
        obj_.outMmRes = outMmRes;
        obj_.outHPre = outHPre;

        return *this;
    }

    AiInfraMainfoldConstrainedHyperConnectionParamsBase Build() const
    {
        return obj_;
    }
private:
    AiInfraMainfoldConstrainedHyperConnectionParamsBase obj_;
};

bool CheckNotNull(const AiInfraMainfoldConstrainedHyperConnectionParamsBase &params)
{
    if (params.x == nullptr) {
        OP_LOGE(ACLNN_ERR_PARAM_NULLPTR, "x tensor is nullptr");
        return false;
    }
    if (params.phi == nullptr) {
        OP_LOGE(ACLNN_ERR_PARAM_NULLPTR, "phi tensor is nullptr");
        return false;
    }
    if (params.alpha == nullptr) {
        OP_LOGE(ACLNN_ERR_PARAM_NULLPTR, "alpha tensor is nullptr");
        return false;
    }
    if (params.bias == nullptr) {
        OP_LOGE(ACLNN_ERR_PARAM_NULLPTR, "bias tensor is nullptr");
        return false;
    }
    if (params.outHin == nullptr) {
        OP_LOGE(ACLNN_ERR_PARAM_NULLPTR, "outHin tensor is nullptr");
        return false;
    }
    if (params.outHPost == nullptr) {
        OP_LOGE(ACLNN_ERR_PARAM_NULLPTR, "outHPost tensor is nullptr");
        return false;
    }
    if (params.outHRes == nullptr) {
        OP_LOGE(ACLNN_ERR_PARAM_NULLPTR, "outHRes tensor is nullptr");
        return false;
    }
    return true;
}

bool CheckEmptyTensor(const AiInfraMainfoldConstrainedHyperConnectionParamsBase &params)
{
    if (params.x->IsEmpty()) {
        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "x tensor is empty");
        return false;
    }
    if (params.phi->IsEmpty()) {
        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "phi tensor is empty");
        return false;
    }
    if (params.alpha->IsEmpty()) {
        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "alpha tensor is empty");
        return false;
    }
    if (params.bias->IsEmpty()) {
        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "bias tensor is empty");
        return false;
    }
    return true;
}

bool CheckInputOutDims(const AiInfraMainfoldConstrainedHyperConnectionParamsBase &params)
{
    constexpr size_t DIM_NUM_1 = 1UL;
    constexpr size_t DIM_NUM_2 = 2UL;
    constexpr size_t DIM_NUM_3 = 3UL;
    constexpr size_t DIM_NUM_4 = 4UL;

    // x可以是3维或4维
    auto xDimNum = params.x->GetViewShape().GetDimNum();
    if (xDimNum != DIM_NUM_3 && xDimNum != DIM_NUM_4) {
        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "x tensor dim num must be 3 or 4, but got %zu", xDimNum);
        return false;
    }

    // phi应该是2维: (n^2+2n, nD)
    auto phiDimNum = params.phi->GetViewShape().GetDimNum();
    if (phiDimNum != DIM_NUM_2) {
        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "phi tensor dim num must be 2, but got %zu", phiDimNum);
        return false;
    }

    // alpha应该是1维: (3)
    auto alphaDimNum = params.alpha->GetViewShape().GetDimNum();
    if (alphaDimNum != DIM_NUM_1) {
        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "alpha tensor dim num must be 1, but got %zu", alphaDimNum);
        return false;
    }

    // bias应该是1维: (n^2+2n)
    auto biasDimNum = params.bias->GetViewShape().GetDimNum();
    if (biasDimNum != DIM_NUM_1) {
        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "bias tensor dim num must be 1, but got %zu", biasDimNum);
        return false;
    }

    // gamma应该是2维: (n, D)
    if (params.gamma != nullptr) {
        auto gammaDimNum = params.gamma->GetViewShape().GetDimNum();
        if (gammaDimNum != DIM_NUM_2) {
            OP_LOGE(ACLNN_ERR_PARAM_INVALID, "gamma tensor dim num must be 2, but got %zu", gammaDimNum);
            return false;
        }
    }

    return true;
}

bool CheckInputOutShape(const AiInfraMainfoldConstrainedHyperConnectionParamsBase &params)
{
    auto xShape = params.x->GetViewShape();
    auto phiShape = params.phi->GetViewShape();
    auto alphaShape = params.alpha->GetViewShape();
    auto biasShape = params.bias->GetViewShape();

    auto xDimNum = xShape.GetDimNum();

    // alpha的shape必须是(3)
    if (alphaShape.GetDim(0) != 3) {
        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "alpha tensor shape must be (3), but got (%ld)", alphaShape.GetDim(0));
        return false;
    }

    // 从x的shape推导n和D
    int64_t n = 0;  // numsResidual
    int64_t d = 0;  // dimen
    int64_t nD = 0; // n * D

    if (xDimNum == 4) { // 4 : 当x的维度为4维
        // BSND格式: (B, S, N, D)
        n = xShape.GetDim(2);  // 2: 获取N维度
        d = xShape.GetDim(3);  // 3: 获取D维度
        nD = n * d;
    } else if (xDimNum == 3) { // 3 : 当x的维度为3维
        // TND格式: (T, N, D)
        n = xShape.GetDim(1);  // 1: 获取N维度
        d = xShape.GetDim(2);  // 2: 获取D维度
        nD = n * d;
    } else {
        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "x tensor dim num must be 3 or 4, but got %zu", xDimNum);
        return false;
    }

    if (n <= 0 || d <= 0) {
        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "Invalid x tensor shape: n=%ld, d=%ld", n, d);
        return false;
    }

    int64_t n2_plus_2n = n * n + 2 * n;  // n^2 + 2n

    // phi的shape应该是(n^2+2n, nD)
    if (phiShape.GetDim(0) != n2_plus_2n) {
        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "phi tensor first dim must be n^2+2n=%ld, but got %ld", n2_plus_2n,
                phiShape.GetDim(0));
        return false;
    }
    if (phiShape.GetDim(1) != nD) {
        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "phi tensor second dim must be nD=%ld, but got %ld", nD, phiShape.GetDim(1));
        return false;
    }
    // bias的shape应该是(n^2+2n)
    if (biasShape.GetDim(0) != n2_plus_2n) {
        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "bias tensor dim must be n^2+2n=%ld, but got %ld", n2_plus_2n,
                biasShape.GetDim(0));
        return false;
    }
    // gamma的shape应该是(n, D)
    if (params.gamma != nullptr) {
        auto gammaShape = params.gamma->GetViewShape();
        if (gammaShape.GetDim(0) != n) {
            OP_LOGE(ACLNN_ERR_PARAM_INVALID, "gamma tensor first dim must be n=%ld, but got %ld", n,
                    gammaShape.GetDim(0));
            return false;
        }
        if (gammaShape.GetDim(1) != d) {
            OP_LOGE(ACLNN_ERR_PARAM_INVALID, "gamma tensor second dim must be D=%ld, but got %ld", d,
                    gammaShape.GetDim(1));
            return false;
        }
    }

    return true;
}

bool CheckDtypeValid(const AiInfraMainfoldConstrainedHyperConnectionParamsBase &params)
{
    // x支持BF16或FP16
    const std::initializer_list<DataType> X_SUPPORT_DTYPE_LIST = {DataType::DT_BF16, DataType::DT_FLOAT16};

    auto xDtype = params.x->GetDataType();
    bool xDtypeValid = false;
    for (const auto &dtype : X_SUPPORT_DTYPE_LIST) {
        if (xDtype == dtype) {
            xDtypeValid = true;
            break;
        }
    }
    if (!xDtypeValid) {
        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "x tensor dtype must be BF16 or FP16");
        return false;
    }

    // phi, gamma, alpha, bias都必须是FP32
    if (params.phi->GetDataType() != DataType::DT_FLOAT) {
        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "phi tensor dtype must be FP32");
        return false;
    }
    if (params.alpha->GetDataType() != DataType::DT_FLOAT) {
        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "alpha tensor dtype must be FP32");
        return false;
    }
    if (params.bias->GetDataType() != DataType::DT_FLOAT) {
        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "bias tensor dtype must be FP32");
        return false;
    }
    if (params.gamma != nullptr) {
        if (params.gamma->GetDataType() != DataType::DT_FLOAT) {
            OP_LOGE(ACLNN_ERR_PARAM_INVALID, "gamma tensor dtype must be FP32");
            return false;
        }
    }

    return true;
}

static bool IsPrivateFormat(ge::Format format)
{
    if (format == ge::FORMAT_NC1HWC0 || format == ge::FORMAT_FRACTAL_Z || format == ge::FORMAT_NDC1HWC0 ||
        format == ge::FORMAT_FRACTAL_Z_3D || format == ge::FORMAT_FRACTAL_NZ || format == ge::FORMAT_NC1HWC0_C04) {
        return true;
    }

    return false;
}

bool CheckFormat(const AiInfraMainfoldConstrainedHyperConnectionParamsBase &params)
{
    // 检查所有输入tensor的format必须是ND格式
    if (IsPrivateFormat(params.x->GetViewFormat())) {
        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "x tensor format must be ND");
        return false;
    }

    if (IsPrivateFormat(params.phi->GetViewFormat())) {
        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "phi tensor format must be ND");
        return false;
    }

    if (IsPrivateFormat(params.alpha->GetViewFormat())) {
        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "alpha tensor format must be ND");
        return false;
    }

    if (IsPrivateFormat(params.bias->GetViewFormat())) {
        OP_LOGE(ACLNN_ERR_PARAM_INVALID, "bias tensor format must be ND");
        return false;
    }

    if (params.gamma != nullptr) {
        if (IsPrivateFormat(params.gamma->GetViewFormat())) {
            OP_LOGE(ACLNN_ERR_PARAM_INVALID, "gamma tensor format must be ND");
            return false;
        }
    }

    return true;
}

aclnnStatus CheckParams(const AiInfraMainfoldConstrainedHyperConnectionParamsBase &params)
{
    // 1. 检查参数是否为空指针、空tensor
    CHECK_RET(CheckNotNull(params), ACLNN_ERR_PARAM_NULLPTR);
    CHECK_RET(CheckEmptyTensor(params), ACLNN_ERR_PARAM_INVALID);

    // 2. 校验输入、输出参数维度
    CHECK_RET(CheckInputOutDims(params), ACLNN_ERR_PARAM_INVALID);

    // 3. 校验输入、输出shape参数
    CHECK_RET(CheckInputOutShape(params), ACLNN_ERR_PARAM_INVALID);

    // 4. 检查输入的数据类型是否在支持的数据类型范围之内
    CHECK_RET(CheckDtypeValid(params), ACLNN_ERR_PARAM_INVALID);

    // 5. 检查数据形状是否支持
    CHECK_RET(CheckFormat(params), ACLNN_ERR_PARAM_INVALID);

    return ACLNN_SUCCESS;
}

aclnnStatus CovertDataContiguous(AiInfraMainfoldConstrainedHyperConnectionParamsBase &params, aclOpExecutor *executor)
{
    // 将输入tensor转换为连续格式
    params.x_contiguous = l0op::Contiguous(params.x, executor);
    CHECK_RET(params.x_contiguous != nullptr, ACLNN_ERR_INNER_NULLPTR);

    params.phi_contiguous = l0op::Contiguous(params.phi, executor);
    CHECK_RET(params.phi_contiguous != nullptr, ACLNN_ERR_INNER_NULLPTR);

    params.alpha_contiguous = l0op::Contiguous(params.alpha, executor);
    CHECK_RET(params.alpha_contiguous != nullptr, ACLNN_ERR_INNER_NULLPTR);

    params.bias_contiguous = l0op::Contiguous(params.bias, executor);
    CHECK_RET(params.bias_contiguous != nullptr, ACLNN_ERR_INNER_NULLPTR);

    if (params.gamma != nullptr) {
        params.gamma_contiguous = l0op::Contiguous(params.gamma, executor);
        CHECK_RET(params.gamma_contiguous != nullptr, ACLNN_ERR_INNER_NULLPTR);
    }

    return ACLNN_SUCCESS;
}

static aclnnStatus aiInfraMHCPreCommonProcess(AiInfraMainfoldConstrainedHyperConnectionParamsBase &params,
                                              aclOpExecutor *executor)
{
    auto ret = CheckParams(params);
    CHECK_RET(ret == ACLNN_SUCCESS, ret);

    ret = CovertDataContiguous(params, executor);
    CHECK_RET(ret == ACLNN_SUCCESS, ret);

    // 使用转换后的连续tensor
    auto outParams = l0op::AiInfraManifoldConstrainedHyperConnectionPre(
        params.x_contiguous, params.phi_contiguous, params.alpha_contiguous, params.bias_contiguous,
        params.gamma_contiguous, params.outFlag, params.normEps, params.hcEps, executor);
    CHECK_RET(outParams != std::tuple(nullptr, nullptr, nullptr, nullptr, nullptr, nullptr), ACLNN_ERR_INNER_NULLPTR);

    auto out0 = std::get<0>(outParams);
    auto ret0 = l0op::ViewCopy(out0, params.outHin, executor);
    CHECK_RET(ret0 != nullptr, ACLNN_ERR_INNER_NULLPTR);

    auto out1 = std::get<1>(outParams);
    auto ret1 = l0op::ViewCopy(out1, params.outHPost, executor);
    CHECK_RET(ret1 != nullptr, ACLNN_ERR_INNER_NULLPTR);

    auto out2 = std::get<2>(outParams);
    auto retView = l0op::ViewCopy(out2, params.outHRes, executor);
    CHECK_RET(retView != nullptr, ACLNN_ERR_INNER_NULLPTR);

    auto out3 = std::get<3>(outParams);
    retView = l0op::ViewCopy(out3, params.outInvRms, executor);
    CHECK_RET(retView != nullptr, ACLNN_ERR_INNER_NULLPTR);

    auto out4 = std::get<4>(outParams);
    retView = l0op::ViewCopy(out4, params.outMmRes, executor);
    CHECK_RET(retView != nullptr, ACLNN_ERR_INNER_NULLPTR);

    auto out5 = std::get<5>(outParams);
    retView = l0op::ViewCopy(out5, params.outHPre, executor);
    CHECK_RET(retView != nullptr, ACLNN_ERR_INNER_NULLPTR);

    return ACLNN_SUCCESS;
}

aclnnStatus aclnnAiInfraManifoldConstrainedHyperConnectionPreGetWorkspaceSize(
    const aclTensor *x, const aclTensor *phi, const aclTensor *alpha, const aclTensor *bias, const aclTensor *gamma,
    int64_t outFlag, double normEps, double hcEps, const aclTensor *outHin, const aclTensor *outHPost,
    const aclTensor *outHRes, const aclTensor *outInvRms, const aclTensor *outMmRes, const aclTensor *outHPre,
    uint64_t *workspaceSize, aclOpExecutor **executor)
{
    L2_DFX_PHASE_1(aclnnAiInfraManifoldConstrainedHyperConnectionPre,
                   DFX_IN(x, phi, alpha, bias, gamma, outFlag, normEps, hcEps),
                   DFX_OUT(outHin, outHPost, outHRes, outInvRms, outMmRes, outHPre));
    auto uniqueExecutor = CREATE_EXECUTOR();

    AiInfraMainfoldConstrainedHyperConnectionParamsBase params =
        AiInfraMainfoldConstrainedHyperConnectionBuilder::Create()
        .SetInput(x, phi, alpha, bias, gamma)
        .SetAttr(outFlag, normEps, hcEps)
        .SetOutput(outHin, outHPost, outHRes)
        .SetOptionalOutput(outInvRms, outMmRes, outHPre)
        .Build();

    auto ret = aiInfraMHCPreCommonProcess(params, uniqueExecutor.get());
    CHECK_RET(ret == ACLNN_SUCCESS, ret);

    *workspaceSize = uniqueExecutor->GetWorkspaceSize();
    uniqueExecutor.ReleaseTo(executor);
    return ACLNN_SUCCESS;
}

aclnnStatus aclnnAiInfraManifoldConstrainedHyperConnectionPre(void *workspace, uint64_t workspaceSize,
                                                              aclOpExecutor *executor, aclrtStream stream)
{
    L2_DFX_PHASE_2(aclnnAiInfraManifoldConstrainedHyperConnectionPre);
    return CommonOpExecutorRun(workspace, workspaceSize, executor, stream);
}
}
#ifdef __cplusplus
}
#endif

