25	const std::tuple<aclTensor *, aclTensor *, aclTensor *, aclTensor *, aclTensor *, aclTensor *>
26	AiInfraManifoldConstrainedHyperConnectionPre(const aclTensor *x, const aclTensor *phi, const aclTensor *alpha,
