41	
42	    auto ret = INFER_SHAPE(AiInfraManifoldConstrainedHyperConnectionPre, OP_INPUT(x, phi, alpha, bias, gamma),
43	                           OP_OUTPUT(outHin, outHpost, outHres, outInvRms, outMmRes, outHpre),
44	                           OP_ATTR(outFlag, static_cast<float>(normEps), static_cast<float>(hcEps)));
45	    OP_CHECK_INFERSHAPE(ret != ACLNN_SUCCESS, return std::tuple(nullptr, nullptr, nullptr, nullptr, nullptr, nullptr),
46	                        "AiInfraManifoldConstrainedHyperConnectionPre InferShape failed.");
47	    auto ret1 =
48	        ADD_TO_LAUNCHER_LIST_AICORE(AiInfraManifoldConstrainedHyperConnectionPre, OP_INPUT(x, phi, alpha, bias, gamma),
49	                                    OP_OUTPUT(outHin, outHpost, outHres, outInvRms, outMmRes, outHpre),
50	                                    OP_ATTR(outFlag, static_cast<float>(normEps), static_cast<float>(hcEps)));
51	    OP_CHECK_ADD_TO_LAUNCHER_LIST_AICORE(
52	        ret1 != ACLNN_SUCCESS, return std::tuple(nullptr, nullptr, nullptr, nullptr, nullptr, nullptr),
53	        "AiInfraManifoldConstrainedHyperConnectionPre ADD_TO_LAUNCHER_LIST_AICORE failed.");
54	
55	    return std::tuple(outHin, outHpost, outHres, outInvRms, outMmRes, outHpre);
56	}
57	}

