#include "ai_infra_manifold_constrained_hyper_connection_pre.h"
#include "aclnn_kernels/common/op_error_check.h"
#include "opdev/make_op_executor.h"
#include "opdev/op_def.h"
#include "opdev/op_dfx.h"
#include "opdev/op_executor.h"
#include "opdev/op_log.h"
#include "opdev/shape_utils.h"

using namespace op;

namespace l0op {
OP_TYPE_REGISTER(AiInfraManifoldConstrainedHyperConnectionPre);

const std::tuple<aclTensor *, aclTensor *, aclTensor *, aclTensor *, aclTensor *, aclTensor *>
AiInfraManifoldConstrainedHyperConnectionPre(const aclTensor *x, const aclTensor *phi, const aclTensor *alpha,
                                             const aclTensor *bias, const aclTensor *gamma, int64_t outFlag,
                                             double normEps, double hcEps, aclOpExecutor *executor)
{
    L0_DFX(AiInfraManifoldConstrainedHyperConnectionPre, x, phi, alpha, bias, gamma, outFlag, normEps, hcEps);

    DataType outType = DataType::DT_FLOAT; // 输出类型
    Format format = Format::FORMAT_ND;     // 输出分形
    auto outHin = executor->AllocTensor(x->GetDataType(), format, format);
    auto outHpost = executor->AllocTensor(outType, format, format);
    auto outHres = executor->AllocTensor(outType, format, format);

    auto outInvRms = executor->AllocTensor(outType, format, format);
    auto outMmRes = executor->AllocTensor(outType, format, format);
    auto outHpre = executor->AllocTensor(outType, format, format);

    auto ret = INFER_SHAPE(AiInfraManifoldConstrainedHyperConnectionPre, OP_INPUT(x, phi, alpha, bias, gamma),
                           OP_OUTPUT(outHin, outHpost, outHres, outInvRms, outMmRes, outHpre),
                           OP_ATTR(outFlag, static_cast<float>(normEps), static_cast<float>(hcEps)));
    OP_CHECK_INFERSHAPE(ret != ACLNN_SUCCESS, return std::tuple(nullptr, nullptr, nullptr, nullptr, nullptr, nullptr),
                        "AiInfraManifoldConstrainedHyperConnectionPre InferShape failed.");
    auto ret1 =
        ADD_TO_LAUNCHER_LIST_AICORE(AiInfraManifoldConstrainedHyperConnectionPre, OP_INPUT(x, phi, alpha, bias, gamma),
                                    OP_OUTPUT(outHin, outHpost, outHres, outInvRms, outMmRes, outHpre),
                                    OP_ATTR(outFlag, static_cast<float>(normEps), static_cast<float>(hcEps)));
    OP_CHECK_ADD_TO_LAUNCHER_LIST_AICORE(
        ret1 != ACLNN_SUCCESS, return std::tuple(nullptr, nullptr, nullptr, nullptr, nullptr, nullptr),
        "AiInfraManifoldConstrainedHyperConnectionPre ADD_TO_LAUNCHER_LIST_AICORE failed.");

    return std::tuple(outHin, outHpost, outHres, outInvRms, outMmRes, outHpre);
}
