84	    LocalTensor<P> hPreBuff_;
85	    LocalTensor<P> hPreBrcb_;
86	    LocalTensor<P> hPostBuff_;
87	    LocalTensor<P> invRmsBuff_;
88	    LocalTensor<P> hMixBuff_;
