92	    LocalTensor<P> broadCastTmpUb_;
93	    LocalTensor<P> matmulRes_;
94	
95	    LocalTensor<T> xLocal_;
96	    LocalTensor<P> invRmsUb_;
97	    LocalTensor<P> xFp32Ub_;
98	
99	    LocalTensor<uint32_t> preOffsetBuf_;
100	    LocalTensor<uint32_t> postOffsetBuf_;
101	    LocalTensor<uint32_t> resOffsetBuf_;
102	
103	    LocalTensor<P> mulFp32Ub_;
104	    LocalTensor<P> oneUb_;
105	
106	    TPipe *pipe_;
107	    MatrixInfo matrixInfo_;
108	    VectorOffsetParams vectorOffset_;
109	
110	    const AiInfraManifoldConstrainedHyperConnectionPreTilingData *tiling_;
111	    
112	    // 运行时状态变量
113	    uint32_t chunTSize_ = 192;
114	    uint32_t v1ChunkDSize_ = 5120;
115	    uint32_t curSingleM_ = 192;  // 当前块的实际大小（可能小于singleM_，如果是最后一个块）
116	    uint32_t curSingleK_ = 512; 
117	    uint32_t coreIdx_ = 0;
118	    uint32_t vecCoreIdx_ = 0;
119	    uint32_t subBlockIdx_ = 0;
120	    float scaleMean_ = 0.0f; // 1/nD
