126	template <class T, class P>
127	__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPreSplitNDKernel<T, P>::Init(InitParams initParams)
128	{
129	    // 1. 绑定GlobalTensor
130	    xGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(initParams.x));
131	    phiGm_.SetGlobalBuffer(reinterpret_cast<__gm__ P *>(initParams.phi));
132	    alphaGm_.SetGlobalBuffer(reinterpret_cast<__gm__ P *>(initParams.alpha));
133	    biasGm_.SetGlobalBuffer(reinterpret_cast<__gm__ P *>(initParams.bias));
134	    hinGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(initParams.hin));
135	    hPostGm_.SetGlobalBuffer(reinterpret_cast<__gm__ P *>(initParams.h_post));
136	    hResGm_.SetGlobalBuffer(reinterpret_cast<__gm__ P *>(initParams.h_res));
137	    hPreGm_.SetGlobalBuffer(reinterpret_cast<__gm__ P *>(initParams.h_pre)); 
138	    xFloatGm_.SetGlobalBuffer(reinterpret_cast<__gm__ P *>(initParams.workspace));
139	
140	    // 2. 获取TilingData进行初始化
141	    tiling_ = initParams.tilingData;
142	    matrixInfo_.totalLength = tiling_->totalLength;
143	    matrixInfo_.nD = tiling_->nD;
144	
145	    N_ = tiling_->N;
146	    D_ = tiling_->D;
147	    matrixInfo_.fusionSize = tiling_->fusionSize;
148	    matrixInfo_.normEps = tiling_->normEps;
149	    matrixInfo_.hcEps = tiling_->hcEps;
150	    coreNum_ = tiling_->coreNum;
151	    totalLength_ = tiling_->totalLength;
152	    scaleMean_ = tiling_->scaleMean;
153	    chunTSize_ = tiling_->chunkTSize;
154	    v1ChunkDSize_ = tiling_->v1ChunkDSize;
155	
156	    mnConfig_.m = matrixInfo_.totalLength;
157	    mnConfig_.n = matrixInfo_.fusionSize;
158	    mnConfig_.k = matrixInfo_.nD;
159	    mnConfig_.singleCoreM = chunTSize_;
160	    mnConfig_.singleCoreN = mnConfig_.n;
161	    mnConfig_.singleCoreK = 256;
162	    mnConfig_.curSingleCoreM = mnConfig_.singleCoreM;
163	    mnConfig_.curSingleCoreN = mnConfig_.singleCoreN;
164	    mnConfig_.curSingleCoreK = mnConfig_.singleCoreK;
165	
166	    uint32_t aicBlockSize = Ceil(Ceil(matrixInfo_.nD, coreNum_), 16) * 16; // 16对齐
167	    c0UsedCoreNum_ = Ceil(matrixInfo_.nD, aicBlockSize);
168	
169	    uint32_t singleNd =
170	        Ceil(Ceil(matrixInfo_.nD, (c0UsedCoreNum_ * 2)), 16) * 16; // 每个vector核处理的Nd的大小，并16对齐
171	    v0ChunkTSize_ = INOUT_QUEUE_SIZE / (singleNd * sizeof(P));     // 根据singleNd的大小调整v0ChunkTSize_
172	    v0ChunkTSize_ = v0ChunkTSize_ > totalLength_ ? totalLength_ : v0ChunkTSize_;
173	
174	    invRmsGm_.SetGlobalBuffer(
175	        reinterpret_cast<__gm__ P *>(initParams.workspace + tiling_->nD * tiling_->totalLength * sizeof(P)));
176	    mmResGm_.SetGlobalBuffer(reinterpret_cast<__gm__ P *>(
177	        initParams.workspace + (tiling_->nD * totalLength_ + totalLength_ * coreNum_ * 2) * sizeof(P)));
178	
179	    // 3. 申请UB
180	    pipe_ = initParams.tPipeIn;
181	    coreIdx_ = GetBlockIdx();
182	    subBlockIdx_ = GetSubBlockIdx();
183	
184	    if ASCEND_IS_AIV {
185	        InitLocalBuffers();
186	        Duplicate<float>(oneUb_, 1.0f, Ceil(v0ChunkTSize_, 8) * 8); // 全为1的tensor，用于计算倒数
187	    }
188	    
189	    SyncAll();
190	}
191	
192	template <class T, class P>
193	__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPreSplitNDKernel<T, P>::InitLocalBuffers()
194	{
195	    pipe_->InitBuffer(xInQueue_, 1, INOUT_QUEUE_SIZE); // 40KB
196	    pipe_->InitBuffer(outQueue_, 1, INOUT_QUEUE_SIZE); // 40KB
197	    pipe_->InitBuffer(invRmsOutQueue_, 1, (Ceil(v0ChunkTSize_, 8) * 8) * sizeof(P)); // 1KB
198	    
199	    pipe_->InitBuffer(tmpBuff_, 105 * 1024); // 105KB
200	
201	    pipe_->InitBuffer(biasInQue_, 1, mnConfig_.n * sizeof(P)); // 1KB
202	    pipe_->InitBuffer(alphaBuf_, mnConfig_.n * sizeof(P)); // 1KB
203	    alphaInUb_ = alphaBuf_.Get<P>();
204	
205	    preOffsetBuf_ = tmpBuff_.GetWithOffset<uint32_t>(uint32_t(mnConfig_.n * V1_BASE_SIZE), 0);
206	    postOffsetBuf_ = preOffsetBuf_[N_ * V1_BASE_SIZE];
207	    resOffsetBuf_ = postOffsetBuf_[N_ * V1_BASE_SIZE];
208	    uint64_t buffOffset = mnConfig_.n * V1_BASE_SIZE * sizeof(uint32_t);
209	    oneUb_ = tmpBuff_.GetWithOffset<P>(uint32_t(Ceil(v0ChunkTSize_, 8) * 8), buffOffset); // 8: 32 bytes对齐
210	
211	    // V0
212	    buffOffset = mnConfig_.n * V1_BASE_SIZE * sizeof(uint32_t) + (Ceil(v0ChunkTSize_, 8) * 8) * sizeof(uint32_t);
213	    mulFp32Ub_ = tmpBuff_.GetWithOffset<P>(uint32_t(INOUT_QUEUE_SIZE / 4), buffOffset);
214	    
215	    // V1
216	    buffOffset = mnConfig_.n * V1_BASE_SIZE * sizeof(uint32_t) + (Ceil(v0ChunkTSize_, 8) * 8) * sizeof(uint32_t);
217	    hPreBuff_ = tmpBuff_.GetWithOffset<P>(uint32_t(V1_BASE_SIZE * N_), buffOffset);
218	    buffOffset += V1_BASE_SIZE * N_ * sizeof(P);
219	    inputBuff_ = tmpBuff_.GetWithOffset<P>(uint32_t(mnConfig_.n * V1_BASE_SIZE * V1_BASE_D), buffOffset);
220	    buffOffset += mnConfig_.n * V1_BASE_SIZE * sizeof(P);
221	    broadCastTmpUb_ = tmpBuff_.GetWithOffset<P>(uint32_t(mnConfig_.n * V1_BASE_SIZE), buffOffset);
222	    buffOffset += mnConfig_.n * V1_BASE_SIZE * sizeof(P);
223	    hPostBuff_ = tmpBuff_.GetWithOffset<P>(uint32_t(V1_BASE_SIZE * N_), buffOffset);
224	    buffOffset += V1_BASE_SIZE * N_ * sizeof(P);
225	    
226	    invRmsBuff_ = tmpBuff_.GetWithOffset<P>(uint32_t(V1_BASE_SIZE), buffOffset);
227	    buffOffset += V1_BASE_SIZE * sizeof(P);
228	    hMixBuff_ = tmpBuff_.GetWithOffset<P>(uint32_t(V1_BASE_SIZE * matrixInfo_.fusionSize), buffOffset);
229	}
230	
231	template <class T, class P>
232	__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPreSplitNDKernel<T, P>::Process()
233	{
234	    // 实现核心计算逻辑
235	    if ASCEND_IS_AIV {
236	        vecCoreIdx_ = GetBlockIdx();
237	        coreIdx_ = vecCoreIdx_ / 2;
238	        V0VectorComputeProcess();
239	        AIVPreLoad();
240	    }
241	    if ASCEND_IS_AIC {
242	        AICProcess();
243	    }
244	    SyncAll<false>();
245	    if ASCEND_IS_AIV {
246	        AIV1Process();
247	        biasInQue_.FreeTensor(biasInUb_);
248	    }
249	}
250	
251	template <class T, class P>
252	__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPreSplitNDKernel<T, P>::AIV1GetHSliceOffset()
253	{
254	    uint32_t offset1 = 0;
255	    uint32_t offset2 = 0;
256	    uint32_t offset3 = 0;
257	    uint32_t curOffset = 0;
258	    uint32_t nSquare = N_ * N_;
259	    for (uint32_t i = 0; i < V1_BASE_SIZE; i++) {
260	        for (uint32_t j = 0; j < N_; j++) {
261	            preOffsetBuf_.SetValue(offset1++, curOffset * sizeof(P));
262	            curOffset++;
263	        }
264	        for (uint32_t j = 0; j < N_; j++) {
265	            postOffsetBuf_.SetValue(offset2++, curOffset * sizeof(P));
266	            curOffset++;
267	        }
268	        for (uint32_t j = 0; j < nSquare; j++) {
269	            resOffsetBuf_.SetValue(offset3++, curOffset * sizeof(P));
270	            curOffset++;
271	        }
272	    }
273	}
274	
275	template <class T, class P>
276	__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPreSplitNDKernel<T, P>::AICProcess()
277	{
278	    uint64_t outOffset = mnConfig_.m * mnConfig_.n * coreIdx_;
279	
280	    mnConfig_.curSingleCoreK = Ceil(matrixInfo_.nD, c0UsedCoreNum_);
281	    if(mnConfig_.curSingleCoreK * coreIdx_ >= matrixInfo_.nD){
282	        return;
283	    }
284	    uint64_t xOffset = mnConfig_.curSingleCoreK * coreIdx_;
285	    uint64_t phiOffset = mnConfig_.curSingleCoreK * coreIdx_;
286	    if(mnConfig_.curSingleCoreK * coreIdx_ + mnConfig_.curSingleCoreK > matrixInfo_.nD){
287	        mnConfig_.curSingleCoreK = matrixInfo_.nD - mnConfig_.curSingleCoreK * coreIdx_;
288	    }
289	    AscendC::CrossCoreWaitFlag(SYNC_V2C);
290	    mm.SetOrgShape(mnConfig_.m, mnConfig_.n, mnConfig_.k);                       // MNK
291	    mm.SetSingleShape(mnConfig_.m, mnConfig_.n, mnConfig_.curSingleCoreK); // SingleCoreMNK
292	    mm.SetTensorA(xFloatGm_[xOffset]);
293	    mm.SetTensorB(phiGm_[phiOffset], true);
294	    mm.IterateAll(mmResGm_[outOffset]);
295	    mm.End();
296	}
297	
298	template <class T, class P>
299	__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPreSplitNDKernel<T, P>::VectorComputeOffset()
300	{
301	    curSingleM_ = Ceil(totalLength_, coreNum_ * 2);
302	    vectorOffset_.offsetMStart = curSingleM_ * vecCoreIdx_;
303	    vectorOffset_.offsetMEnd = vectorOffset_.offsetMStart + curSingleM_ > totalLength_ ? 
304	                               totalLength_ : vectorOffset_.offsetMStart + curSingleM_;
305	    vectorOffset_.singleCoreM = vectorOffset_.offsetMEnd - vectorOffset_.offsetMStart;
306	}
307	
308	template <class T, class P>
309	__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPreSplitNDKernel<T, P>::VectorComputeOffsetV0()
310	{
311	    curSingleK_ = Ceil(matrixInfo_.nD, c0UsedCoreNum_);
312	    uint64_t aliginSingleK = Ceil(curSingleK_ / 2, 8) * 8; // 32Byte对齐
313	    vectorOffset_.singleCoreK = aliginSingleK <  curSingleK_ ? aliginSingleK : curSingleK_;
314	    if (subBlockIdx_ == 0) {
315	        vectorOffset_.offsetK = curSingleK_ * coreIdx_;
316	    } else {
317	        vectorOffset_.offsetK = curSingleK_ * coreIdx_ + aliginSingleK;
318	        vectorOffset_.singleCoreK = curSingleK_ - vectorOffset_.singleCoreK;
319	    }
320	}
321	
322	template <class T, class P>
323	__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPreSplitNDKernel<T, P>::V0VectorComputeProcess()
324	{
325	    curSingleM_= totalLength_;
326	    VectorComputeOffsetV0(); // 计算0核和1核的偏移
327	
328	    if (vectorOffset_.offsetK > matrixInfo_.nD || vectorOffset_.singleCoreK <= 0) {
329	        CrossCoreSetFlag<0x2, PIPE_MTE3>(SYNC_V2C);
330	        return;
331	    }
332	
333	    uint64_t computeLen = curSingleM_ * vectorOffset_.singleCoreK;
334	    uint64_t curNdLen = vectorOffset_.singleCoreK;
335	    if (vectorOffset_.offsetK + vectorOffset_.singleCoreK >= matrixInfo_.nD) {
336	        curNdLen = matrixInfo_.nD - vectorOffset_.offsetK;
337	    }
338	    for (uint64_t offsetT = 0; offsetT < totalLength_; offsetT += v0ChunkTSize_) {
339	        uint32_t curMLen = offsetT + v0ChunkTSize_ < totalLength_ ? v0ChunkTSize_ : totalLength_ - offsetT;
340	        computeLen = curMLen * Ceil(curNdLen, 16) * 16;
341	        // copy x
342	        xLocal_ = xInQueue_.AllocTensor<T>();
343	        DataCopyX(curMLen, curNdLen, offsetT, vectorOffset_.offsetK);
344	        xLocal_ = xInQueue_.DeQue<T>();
345	
346	        // bf16转fp32
347	        xFp32Ub_ = outQueue_.AllocTensor<P>();
348	        Cast(xFp32Ub_, xLocal_, AscendC::RoundMode::CAST_NONE, computeLen);
349	        PipeBarrier<PIPE_V>();
350	        Mul(mulFp32Ub_, xFp32Ub_, xFp32Ub_, computeLen);
351	
352	        PipeBarrier<PIPE_V>();
353	        DataCopyOutToWorkSpace(curMLen, curNdLen, offsetT, vectorOffset_.offsetK);
354	        PipeBarrier<PIPE_V>();
355	        uint32_t srcShape[2] = {curMLen, Ceil(curNdLen, 16) * 16};
356	        invRmsUb_ = invRmsOutQueue_.AllocTensor<P>();
357	        ReduceSum<float, AscendC::Pattern::Reduce::AR, true>(invRmsUb_, mulFp32Ub_, srcShape, true);
358	        DataCopyOutInvRmsUb(curMLen, offsetT);
359	        xInQueue_.FreeTensor(xLocal_);
360	        outQueue_.FreeTensor(xFp32Ub_);
361	        invRmsOutQueue_.FreeTensor(invRmsUb_);
362	    }
363	    CrossCoreSetFlag<0x2, PIPE_MTE3>(SYNC_V2C);
364	}
365	
366	template <class T, class P>
367	__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPreSplitNDKernel<T, P>::AIV1Process()
368	{
369	    VectorComputeOffset(); // 计算0核和1核的偏移
370	    if (vectorOffset_.singleCoreM <= 0) {
371	        return;
372	    }
373	    uint64_t lenT = 0;
374	    uint64_t lenD = 0;
375	    uint64_t singleCoreOffset = 0;
376	    for (int offsetT = vectorOffset_.offsetMStart; offsetT < vectorOffset_.offsetMEnd; offsetT += V1_BASE_SIZE) {
377	        lenT = V1_BASE_SIZE < vectorOffset_.offsetMEnd - offsetT ? V1_BASE_SIZE : vectorOffset_.offsetMEnd - offsetT;
378	        lenD = v1ChunkDSize_;
379	        // H 切分
380	        AIV1Prologue(offsetT, lenT, singleCoreOffset);
381	        AIV1ProcessHPost(offsetT, lenT);
382	        AIV1ProcessHPre(offsetT, lenT);
383	        auto hInDealBuf = inputBuff_; // 最大80K
384	        auto reduceResult = hInDealBuf[lenD * N_]; // 最大10K
385	        PipeBarrier<PIPE_ALL>();
386	        for (uint32_t tIdx = 0; tIdx < lenT; tIdx++) {
387	            for (int offsetD = 0; offsetD < D_; offsetD += v1ChunkDSize_) {
388	                lenD = v1ChunkDSize_ < D_ - offsetD ? v1ChunkDSize_ : D_ - offsetD;
389	                uint32_t ubOffset = 0;
390	                const uint32_t srcReduceShape_[2] = {static_cast<uint32_t>(N_), static_cast<uint32_t>(lenD)};
391	                for (uint32_t nIdx = 0; nIdx < N_; nIdx++) {
392	                    uint64_t xGmOffset = (globalOffsetM_ + offsetT + tIdx) * N_ * D_ + nIdx * D_ + offsetD;
393	
394	                    LocalTensor<T> xIn = xInQueue_.AllocTensor<T>();
395	                    // copy X
396	                    DataCopyExtParams copyParams;
397	                    copyParams.blockCount = static_cast<uint16_t>(1);
398	                    copyParams.blockLen = uint32_t(lenD * sizeof(T));
399	                    copyParams.srcStride = 0;
400	                    copyParams.dstStride = 0;
401	
402	                    uint32_t rightPadNum = Ceil(lenD, 16) * 16 - lenD;
403	                    DataCopyPadExtParams<T> padParams{true, 0, static_cast<uint8_t>(rightPadNum), 0};
404	                    DataCopyPad(xIn, xGm_[xGmOffset], copyParams, padParams);
405	
406	                    xInQueue_.EnQue(xIn);
407	                    xIn = xInQueue_.DeQue<T>();
408	
409	                    Cast(hInDealBuf[ubOffset], xIn, RoundMode::CAST_NONE, lenD);
410	                    PipeBarrier<PIPE_V>();
411	                    xInQueue_.FreeTensor(xIn);
412	
413	                    Muls(hInDealBuf[ubOffset], hInDealBuf[ubOffset], hPreBuff_.GetValue(tIdx * N_ + nIdx), lenD);
414	                    PipeBarrier<PIPE_V>();
415	                    ubOffset += lenD;
416	                }
417	
418	                // reducesum 
419	                ReduceSum<P, Pattern::Reduce::RA, true>(reduceResult, hInDealBuf, srcReduceShape_, true);
420	                PipeBarrier<PIPE_V>();
421	
422	                // cast
423	                LocalTensor<T> hinOut = outQueue_.AllocTensor<T>();
424	                Cast(hinOut, reduceResult, RoundMode::CAST_RINT, lenD);
425	                PipeBarrier<PIPE_V>();
426	    
427	                outQueue_.EnQue(hinOut);
428	                hinOut = outQueue_.DeQue<T>();
429	                // copyout
430	                DataCopyExtParams copyParams;
431	                copyParams.blockCount = 1; // 行数
432	                copyParams.blockLen = uint32_t(lenD * sizeof(T));
433	                copyParams.srcStride = 0;
434	                copyParams.dstStride = 0;
435	
436	                DataCopyPad(hinGm_[(globalOffsetM_ + offsetT + tIdx) * D_ + offsetD], hinOut, copyParams);
437	                PipeBarrier<PIPE_V>();
438	                outQueue_.FreeTensor(hinOut);
439	            }
440	        }
441	    }
442	}
443	
444	template <class T, class P>
445	__aicore__ inline void
446	AiInfraManifoldConstrainedHyperConnectionPreSplitNDKernel<T, P>::AIV1Prologue(uint64_t offsetT, uint64_t lenT,
447	                                                                              uint64_t singleCoreOffset)
448	{
449	    LocalTensor<P> hResOutLocal = outQueue_.AllocTensor<P>();
450	    uint64_t HMixOffset = 0;
451	    HMixOffset = offsetT * mnConfig_.n;
452	    InvRmsCopyIn(offsetT, lenT);
453	    LocalTensor<P> invRmsInLocal = xInQueue_.DeQue<P>(); 
454	    uint32_t srcShape[] = {uint32_t(c0UsedCoreNum_ * 2), uint32_t(Ceil(lenT, 8) * 8)};
455	    ReduceSum<P, Pattern::Reduce::RA, true>(invRmsBuff_, invRmsInLocal, srcShape, true);
456	    xInQueue_.FreeTensor(invRmsInLocal);
457	    PipeBarrier<PIPE_V>();
458	    Muls(invRmsBuff_, invRmsBuff_, scaleMean_, lenT);
459	    PipeBarrier<PIPE_V>();
460	
461	    Adds(invRmsBuff_, invRmsBuff_, matrixInfo_.normEps, lenT);
462	    PipeBarrier<PIPE_V>();
463	
464	    Sqrt(invRmsBuff_, invRmsBuff_, lenT);
465	    PipeBarrier<PIPE_V>();
466	    Div(invRmsBuff_, oneUb_, invRmsBuff_, lenT);
467	    PipeBarrier<PIPE_V>();
468	
469	    uint32_t hMixShape[] = {uint32_t(lenT), uint32_t(mnConfig_.n)};
470	    uint32_t alphaBiaShape[] = {uint32_t(1), uint32_t(mnConfig_.n)};
471	    uint32_t rShape[] = {uint32_t(lenT), uint32_t(1)};
472	    HMixCopyIn(HMixOffset, lenT);
473	    matmulRes_ = xInQueue_.DeQue<P>(); 
474	    srcShape[0] = uint32_t(c0UsedCoreNum_);
475	    srcShape[1] = uint32_t(lenT * matrixInfo_.fusionSize);
476	    ReduceSum<P, Pattern::Reduce::RA, true>(hMixBuff_, matmulRes_, srcShape, true);
477	    xInQueue_.FreeTensor(matmulRes_);
478	
479	    Broadcast<P, 2, 1>(broadCastTmpUb_, invRmsBuff_, hMixShape, rShape);
480	    pipe_barrier(PIPE_V);
481	    hMixBuff_ = hMixBuff_ * broadCastTmpUb_;
482	    pipe_barrier(PIPE_V);
483	    Broadcast<P, 2, 0>(broadCastTmpUb_, alphaInUb_, hMixShape, alphaBiaShape);
484	    pipe_barrier(PIPE_V);
485	    hMixBuff_ = hMixBuff_ * broadCastTmpUb_;
486	    pipe_barrier(PIPE_V);
487	    Broadcast<P, 2, 0>(broadCastTmpUb_, biasInUb_, hMixShape, alphaBiaShape);
488	    pipe_barrier(PIPE_V);
489	    hMixBuff_ = hMixBuff_ + broadCastTmpUb_;
490	    pipe_barrier(PIPE_V);
491	
492	    SetFlag<HardEvent::MTE2_V>(EVENT_ID1);
493	    WaitFlag<HardEvent::MTE2_V>(EVENT_ID1);
494	
495	    Gather(hPreBuff_, hMixBuff_, preOffsetBuf_, uint32_t(0), lenT * N_);
496	    Gather(hPostBuff_, hMixBuff_, postOffsetBuf_, uint32_t(0), lenT * N_);
497	    Gather(hResOutLocal, hMixBuff_, resOffsetBuf_, uint32_t(0), lenT * N_ * N_);
498	    PipeBarrier<PIPE_V>();
499	    outQueue_.EnQue(hResOutLocal);
500	    hResOutLocal = outQueue_.DeQue<P>();
501	    DataCopyExtParams copyParams;
502	    copyParams.blockCount = static_cast<uint16_t>(1);
503	    copyParams.blockLen = uint32_t(lenT * N_ * N_ * sizeof(P));
504	    copyParams.srcStride = uint32_t(0);
505	    copyParams.dstStride = uint32_t(0);
506	    DataCopyPad(hResGm_[offsetT * N_ * N_], hResOutLocal, copyParams);
507	    outQueue_.FreeTensor(hResOutLocal);
508	}
509	
510	template <class T, class P>
511	__aicore__ inline void
512	AiInfraManifoldConstrainedHyperConnectionPreSplitNDKernel<T, P>::AIV1ProcessHPre(uint64_t offsetT, uint64_t lenT)
513	{
514	    uint64_t offset = globalOffsetM_ + offsetT;
515	    LocalTensor<P> hPreSigmoid = inputBuff_;
516	
517	    Sigmoid(hPreSigmoid, hPreBuff_, lenT * N_);
518	    PipeBarrier<PIPE_V>();
519	    Adds(hPreBuff_, hPreSigmoid, matrixInfo_.hcEps, lenT * N_);
520	    PipeBarrier<PIPE_V>();
521	}
522	
523	template <class T, class P>
524	__aicore__ inline void
525	AiInfraManifoldConstrainedHyperConnectionPreSplitNDKernel<T, P>::AIV1ProcessHPost(uint64_t offsetT, uint64_t lenT)
526	{
527	    uint64_t offset = globalOffsetM_ + offsetT;
528	    LocalTensor<P> hPostSigmoid = broadCastTmpUb_;
529	    LocalTensor<P> hPostOutLocal = outQueue_.AllocTensor<P>();
530	    Sigmoid(hPostSigmoid, hPostBuff_);
531	    PipeBarrier<PIPE_V>();
532	    Muls(hPostOutLocal, hPostSigmoid, static_cast<float>(2.0), lenT * N_);
533	    PipeBarrier<PIPE_V>();
534	    outQueue_.EnQue(hPostOutLocal);
535	    hPostOutLocal = outQueue_.DeQue<P>();
536	    DataCopyExtParams copyParams;
537	    copyParams.blockCount = static_cast<uint16_t>(1);
538	    copyParams.blockLen = uint32_t(lenT * N_ * sizeof(P));
539	    copyParams.srcStride = uint32_t(0);
540	    copyParams.dstStride = uint32_t(0);
541	    DataCopyPad(hPostGm_[offset * N_], hPostOutLocal, copyParams);
542	    outQueue_.FreeTensor(hPostOutLocal);
543	}
544	
545	template <class T, class P>
546	__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPreSplitNDKernel<T, P>::AIVPreLoad()
547	{
548	    AIV1GetHSliceOffset();
549	    float alphaPre = alphaGm_.GetValue(0);
550	    float alphaPost = alphaGm_.GetValue(1);
551	    float alphaComb = alphaGm_.GetValue(2);
552	    for(uint64_t i = 0; i < N_; ++i){
553	        alphaInUb_.SetValue(i, alphaPre);
554	        alphaInUb_.SetValue(i + N_, alphaPost);
555	        for(uint64_t j = 0; j < N_; ++j){
556	            alphaInUb_.SetValue((2 + i) * N_ + j, alphaComb);
557	        }
558	    }
559	    BiasCopyIn();
560	    biasInUb_ = biasInQue_.DeQue<P>();
561	}
562	
563	template <class T, class P>
564	__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPreSplitNDKernel<T, P>::BiasCopyIn()
565	{
566	    LocalTensor<P> biasLocal = biasInQue_.AllocTensor<P>();
567	    DataCopyExtParams copyParams;
568	    copyParams.blockCount = static_cast<uint16_t>(1); // 行数
569	    copyParams.blockLen = uint32_t(matrixInfo_.fusionSize * sizeof(P));
570	    copyParams.srcStride = uint32_t(0); // 相邻块的间隔
571	    copyParams.dstStride = uint32_t(0);                                                   // 相邻块的间隔
572	    DataCopyPadExtParams<P> copyPadParams{true, 0, 0, 0};
573	
574	    DataCopyPad(biasLocal, biasGm_, copyParams, copyPadParams);
575	    biasInQue_.EnQue(biasLocal);
576	}
577	
578	template <class T, class P>
579	__aicore__ inline void
580	AiInfraManifoldConstrainedHyperConnectionPreSplitNDKernel<T, P>::DataCopyX(uint32_t curMLen, uint32_t curNdLen,
581	                                                                           uint32_t offsetT, uint32_t offsetNd)
582	{
583	    DataCopyExtParams copyParams;
584	    copyParams.blockCount = static_cast<uint16_t>(curMLen);
585	    copyParams.blockLen = uint32_t(curNdLen * sizeof(T));
586	    copyParams.srcStride = uint32_t((matrixInfo_.nD - curNdLen) * sizeof(T));
587	    copyParams.dstStride = uint32_t(0);
588	    uint32_t rightPadNum = Ceil(curNdLen, 16) * 16 - curNdLen;
589	    DataCopyPadExtParams<T> padParams{true, 0, static_cast<uint8_t>(rightPadNum), 0};
590	
591	    uint64_t offset = offsetT * matrixInfo_.nD + offsetNd;
592	    DataCopyPad(xLocal_, xGm_[offset], copyParams, padParams);
593	    xInQueue_.EnQue<T>(xLocal_);
594	}
595	
596	template <class T, class P>
597	__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPreSplitNDKernel<T, P>::HMixCopyIn(uint64_t offset,
598	                                                                                                   uint64_t lenT)
599	{
600	    LocalTensor<P> hMixLocal = xInQueue_.AllocTensor<P>();
601	    DataCopyExtParams copyParams;
602	    copyParams.blockCount = static_cast<uint16_t>(c0UsedCoreNum_); // 行数
603	    copyParams.blockLen = uint32_t(lenT * mnConfig_.n * sizeof(P));
604	    copyParams.srcStride = uint32_t((totalLength_ - lenT) * mnConfig_.n * sizeof(P)); // 相邻块的间隔
605	    copyParams.dstStride = uint32_t(0);                                                   // 相邻块的间隔
606	    DataCopyPadExtParams<P> copyPadParams{true, 0, 0, 0};
607	
608	    DataCopyPad(hMixLocal, mmResGm_[offset], copyParams, copyPadParams);
609	    xInQueue_.EnQue(hMixLocal);
610	}
611	
612	template <class T, class P>
613	__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPreSplitNDKernel<T, P>::InvRmsCopyIn(uint64_t offsetT,
614	                                                                                                     uint32_t lenT)
615	{
616	    LocalTensor<P> invRmsInLocal = xInQueue_.AllocTensor<P>();
617	    DataCopyExtParams copyParams;
618	    copyParams.blockCount = static_cast<uint16_t>(c0UsedCoreNum_ * 2); // 行数
619	    copyParams.blockLen = uint32_t(lenT * sizeof(P));
620	    copyParams.srcStride = uint32_t((totalLength_ - lenT) * sizeof(P)); // 相邻块的间隔
621	    copyParams.dstStride = uint32_t(0);                                                   // 相邻块的间隔
622	    DataCopyPadExtParams<P> copyPadParams{true, 0, 0, 0};
623	
624	    DataCopyPad(invRmsInLocal, invRmsGm_[offsetT], copyParams, copyPadParams);
625	    xInQueue_.EnQue(invRmsInLocal);
626	}
627	
628	template <class T, class P>
629	__aicore__ inline void
630	AiInfraManifoldConstrainedHyperConnectionPreSplitNDKernel<T, P>::DataCopyOutInvRmsUb(uint32_t curMLen, uint32_t offsetT)
631	{
632	    invRmsOutQueue_.EnQue<P>(invRmsUb_);
633	    invRmsUb_ = invRmsOutQueue_.DeQue<P>();
634	
635	    DataCopyExtParams copyParams;
636	    copyParams.blockCount = static_cast<uint16_t>(1);
637	    copyParams.blockLen = uint32_t(curMLen * sizeof(P));
638	    copyParams.srcStride = uint32_t(0);
639	    copyParams.dstStride = uint32_t(0);
640	
641	    uint64_t offset = (coreIdx_ * 2 + subBlockIdx_) * totalLength_ + offsetT;
642	    DataCopyPad(invRmsGm_[offset], invRmsUb_, copyParams);
643	}
644	
645	template <class T, class P>
646	__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPreSplitNDKernel<T, P>::DataCopyOutToWorkSpace(
647	    uint32_t curMLen, uint32_t curNdLen, uint32_t offsetT, uint32_t offsetNd)
648	{
649	    uint32_t aliginNdStride = 0;
650	    if (curNdLen % 16 <= 8 && curNdLen % 16 > 0) { // curNdLen对16取余大于0且小于8时，srcStride需为1.
651	        aliginNdStride = 1;
652	    }
653	
654	    outQueue_.EnQue<P>(xFp32Ub_);
655	    xFp32Ub_ = outQueue_.DeQue<P>();
656	
657	    DataCopyExtParams copyParams;
658	    copyParams.blockCount = static_cast<uint16_t>(curMLen);
659	    copyParams.blockLen = uint32_t(curNdLen * sizeof(P));
660	    copyParams.srcStride = uint32_t(aliginNdStride);
661	    copyParams.dstStride = uint32_t((matrixInfo_.nD - curNdLen) * sizeof(P));
662	
663	    uint64_t offset = offsetT * matrixInfo_.nD + offsetNd;
664	    DataCopyPad(xFloatGm_[offset], xFp32Ub_, copyParams);
665	}
