/*!
 * \file ai_infra_manifold_constrained_hyper_connection_split_N.h
 * \brief
 */

#ifndef __MANIFOLD_CONSTRAINED_HYPER_CONNECTION_PRE_SPLIT_ND_KERNEL_H_
#define __MANIFOLD_CONSTRAINED_HYPER_CONNECTION_PRE_SPLIT_ND_KERNEL_H_

#include "kernel_operator.h"
#include "lib/matmul_intf.h"
#include "kernel_tiling/kernel_tiling.h"

namespace AiInfraManifoldConstrainedHyperConnectionPre {

using namespace matmul;
using namespace AscendC;

constexpr uint32_t INOUT_QUEUE_SIZE = 40 * 1024;  // 40KB
constexpr uint32_t V1_BASE_SIZE = 8;

template <class T, class P>
class AiInfraManifoldConstrainedHyperConnectionPreSplitNDKernel {
public:
    __aicore__ inline AiInfraManifoldConstrainedHyperConnectionPreSplitNDKernel(MT &matmul) : mm(matmul) {}
    __aicore__ inline void Init(InitParams initParams);
    __aicore__ inline void Process();
    __aicore__ inline void AICProcess();
    __aicore__ inline void InitLocalBuffers();
    __aicore__ inline void VectorComputeOffset();
    __aicore__ inline void VectorComputeOffsetV0();
    __aicore__ inline void V0VectorComputeProcess();
    __aicore__ inline void DataCopyX(uint32_t curMLen, uint32_t curNdLen, uint32_t offsetT, uint32_t offsetNd);
    __aicore__ inline void DataCopyOutInvRmsUb(uint32_t curMLen, uint32_t offsetT);
    __aicore__ inline void InvRmsCopyIn(uint64_t offsetT, uint32_t lenT);
    __aicore__ inline void DataCopyOutToWorkSpace(uint32_t curMLen, uint32_t curNdLen, uint32_t offsetT,
                                                  uint32_t offsetNd);
    __aicore__ inline void AIVPreLoad();
    __aicore__ inline void HMixCopyIn(uint64_t offset, uint64_t lenT);
    __aicore__ inline void AIV1ProcessHPost(uint64_t offsetT, uint64_t lenT);
    __aicore__ inline void AIV1ProcessHPre(uint64_t offsetT, uint64_t lenT);
    __aicore__ inline void AIV1Prologue(uint64_t offsetT, uint64_t lenT, uint64_t singleCoreOffset);
    __aicore__ inline void AIV1Process();
    __aicore__ inline void BiasCopyIn();
    __aicore__ inline void AIV1GetHSliceOffset();
private:
    MT &mm;
    MNConfig mnConfig_;
    uint32_t coreNum_;
    uint64_t totalLength_;
    uint64_t N_;
    uint64_t D_;

    GlobalTensor<T> xGm_;      // 输入 x
    GlobalTensor<P> phiGm_;    // 输入 phi
    GlobalTensor<P> alphaGm_;  // 输入 alpha
    GlobalTensor<P> biasGm_;   // 输入 bias
    GlobalTensor<T> hinGm_;    // 输出 hin
    GlobalTensor<P> hPostGm_;  // 输出 h_post
    GlobalTensor<P> hResGm_;   // 输出 h_res
    GlobalTensor<P> invRmsGm_;   // 输出 h_res
    GlobalTensor<P> mmResGm_;   // 输出 h_res
    GlobalTensor<P> hPreGm_;   // 输出 h_res
    GlobalTensor<P> xFloatGm_;

    TQue<QuePosition::VECIN, 1> xInQueue_;
    TQue<QuePosition::VECOUT, 1> invRmsOutQueue_;
    TQue<QuePosition::VECOUT, 1> outQueue_;
    TQue<QuePosition::VECIN, 1> biasInQue_;

    TBuf<TPosition::VECCALC> tmpBuff_;
    TBuf<TPosition::VECCALC> alphaBuf_;

    LocalTensor<P> inputBuff_;
    LocalTensor<P> hPreBuff_;
    LocalTensor<P> hPreBrcb_;
    LocalTensor<P> hPostBuff_;
    LocalTensor<P> invRmsBuff_;
    LocalTensor<P> hMixBuff_;

    LocalTensor<P> alphaInUb_;
    LocalTensor<P> biasInUb_;
    LocalTensor<P> broadCastTmpUb_;
    LocalTensor<P> matmulRes_;

    LocalTensor<T> xLocal_;
    LocalTensor<P> invRmsUb_;
    LocalTensor<P> xFp32Ub_;

    LocalTensor<uint32_t> preOffsetBuf_;
    LocalTensor<uint32_t> postOffsetBuf_;
    LocalTensor<uint32_t> resOffsetBuf_;

    LocalTensor<P> mulFp32Ub_;
    LocalTensor<P> oneUb_;

    TPipe *pipe_;
    MatrixInfo matrixInfo_;
    VectorOffsetParams vectorOffset_;

    const AiInfraManifoldConstrainedHyperConnectionPreTilingData *tiling_;

    // 运行时状态变量
    uint32_t chunTSize_ = 192;
    uint32_t v1ChunkDSize_ = 5120;
    uint32_t curSingleM_ = 192;  // 当前块的实际大小（可能小于singleM_，如果是最后一个块）
    uint32_t curSingleK_ = 512; 
    uint32_t coreIdx_ = 0;
    uint32_t vecCoreIdx_ = 0;
    uint32_t subBlockIdx_ = 0;
    float scaleMean_ = 0.0f; // 1/nD
    uint64_t globalOffsetM_ = 0;
    uint32_t v0ChunkTSize_ = 6;
    uint32_t c0UsedCoreNum_ = 0;
};

template <class T, class P>
__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPreSplitNDKernel<T, P>::Init(InitParams initParams)
{
    // 1. 绑定GlobalTensor
    xGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(initParams.x));
    phiGm_.SetGlobalBuffer(reinterpret_cast<__gm__ P *>(initParams.phi));
    alphaGm_.SetGlobalBuffer(reinterpret_cast<__gm__ P *>(initParams.alpha));
    biasGm_.SetGlobalBuffer(reinterpret_cast<__gm__ P *>(initParams.bias));
    hinGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(initParams.hin));
    hPostGm_.SetGlobalBuffer(reinterpret_cast<__gm__ P *>(initParams.h_post));
    hResGm_.SetGlobalBuffer(reinterpret_cast<__gm__ P *>(initParams.h_res));
    hPreGm_.SetGlobalBuffer(reinterpret_cast<__gm__ P *>(initParams.h_pre)); 
    xFloatGm_.SetGlobalBuffer(reinterpret_cast<__gm__ P *>(initParams.workspace));

    // 2. 获取TilingData进行初始化
    tiling_ = initParams.tilingData;
    matrixInfo_.totalLength = tiling_->totalLength;
    matrixInfo_.nD = tiling_->nD;

    N_ = tiling_->N;
    D_ = tiling_->D;
    matrixInfo_.fusionSize = tiling_->fusionSize;
    matrixInfo_.normEps = tiling_->normEps;
    matrixInfo_.hcEps = tiling_->hcEps;
    coreNum_ = tiling_->coreNum;
    totalLength_ = tiling_->totalLength;
    scaleMean_ = tiling_->scaleMean;
    chunTSize_ = tiling_->chunkTSize;
    v1ChunkDSize_ = tiling_->v1ChunkDSize;

    mnConfig_.m = matrixInfo_.totalLength;
    mnConfig_.n = matrixInfo_.fusionSize;
    mnConfig_.k = matrixInfo_.nD;
    mnConfig_.singleCoreM = chunTSize_;
    mnConfig_.singleCoreN = mnConfig_.n;
    mnConfig_.singleCoreK = 256;
    mnConfig_.curSingleCoreM = mnConfig_.singleCoreM;
    mnConfig_.curSingleCoreN = mnConfig_.singleCoreN;
    mnConfig_.curSingleCoreK = mnConfig_.singleCoreK;

    uint32_t aicBlockSize = Ceil(Ceil(matrixInfo_.nD, coreNum_), 16) * 16; // 16对齐
    c0UsedCoreNum_ = Ceil(matrixInfo_.nD, aicBlockSize);

    uint32_t singleNd =
        Ceil(Ceil(matrixInfo_.nD, (c0UsedCoreNum_ * 2)), 16) * 16; // 每个vector核处理的Nd的大小，并16对齐
    v0ChunkTSize_ = INOUT_QUEUE_SIZE / (singleNd * sizeof(P));     // 根据singleNd的大小调整v0ChunkTSize_
    v0ChunkTSize_ = v0ChunkTSize_ > totalLength_ ? totalLength_ : v0ChunkTSize_;

    invRmsGm_.SetGlobalBuffer(
        reinterpret_cast<__gm__ P *>(initParams.workspace + tiling_->nD * tiling_->totalLength * sizeof(P)));
    mmResGm_.SetGlobalBuffer(reinterpret_cast<__gm__ P *>(
        initParams.workspace + (tiling_->nD * totalLength_ + totalLength_ * coreNum_ * 2) * sizeof(P)));

    // 3. 申请UB
    pipe_ = initParams.tPipeIn;
    coreIdx_ = GetBlockIdx();
    subBlockIdx_ = GetSubBlockIdx();

    if ASCEND_IS_AIV {
        InitLocalBuffers();
        Duplicate<float>(oneUb_, 1.0f, Ceil(v0ChunkTSize_, 8) * 8); // 全为1的tensor，用于计算倒数
    }

    SyncAll();
}

template <class T, class P>
__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPreSplitNDKernel<T, P>::InitLocalBuffers()
{
    pipe_->InitBuffer(xInQueue_, 1, INOUT_QUEUE_SIZE); // 40KB
    pipe_->InitBuffer(outQueue_, 1, INOUT_QUEUE_SIZE); // 40KB
    pipe_->InitBuffer(invRmsOutQueue_, 1, (Ceil(v0ChunkTSize_, 8) * 8) * sizeof(P)); // 1KB

    pipe_->InitBuffer(tmpBuff_, 105 * 1024); // 105KB

    pipe_->InitBuffer(biasInQue_, 1, mnConfig_.n * sizeof(P)); // 1KB
    pipe_->InitBuffer(alphaBuf_, mnConfig_.n * sizeof(P)); // 1KB
    alphaInUb_ = alphaBuf_.Get<P>();

    preOffsetBuf_ = tmpBuff_.GetWithOffset<uint32_t>(uint32_t(mnConfig_.n * V1_BASE_SIZE), 0);
    postOffsetBuf_ = preOffsetBuf_[N_ * V1_BASE_SIZE];
    resOffsetBuf_ = postOffsetBuf_[N_ * V1_BASE_SIZE];
    uint64_t buffOffset = mnConfig_.n * V1_BASE_SIZE * sizeof(uint32_t);
    oneUb_ = tmpBuff_.GetWithOffset<P>(uint32_t(Ceil(v0ChunkTSize_, 8) * 8), buffOffset); // 8: 32 bytes对齐

    // V0
    buffOffset = mnConfig_.n * V1_BASE_SIZE * sizeof(uint32_t) + (Ceil(v0ChunkTSize_, 8) * 8) * sizeof(uint32_t);
    mulFp32Ub_ = tmpBuff_.GetWithOffset<P>(uint32_t(INOUT_QUEUE_SIZE / 4), buffOffset);

    // V1
    buffOffset = mnConfig_.n * V1_BASE_SIZE * sizeof(uint32_t) + (Ceil(v0ChunkTSize_, 8) * 8) * sizeof(uint32_t);
    hPreBuff_ = tmpBuff_.GetWithOffset<P>(uint32_t(V1_BASE_SIZE * N_), buffOffset);
    buffOffset += V1_BASE_SIZE * N_ * sizeof(P);
    inputBuff_ = tmpBuff_.GetWithOffset<P>(uint32_t(mnConfig_.n * V1_BASE_SIZE * V1_BASE_D), buffOffset);
    buffOffset += mnConfig_.n * V1_BASE_SIZE * sizeof(P);
    broadCastTmpUb_ = tmpBuff_.GetWithOffset<P>(uint32_t(mnConfig_.n * V1_BASE_SIZE), buffOffset);
    buffOffset += mnConfig_.n * V1_BASE_SIZE * sizeof(P);
    hPostBuff_ = tmpBuff_.GetWithOffset<P>(uint32_t(V1_BASE_SIZE * N_), buffOffset);
    buffOffset += V1_BASE_SIZE * N_ * sizeof(P);

    invRmsBuff_ = tmpBuff_.GetWithOffset<P>(uint32_t(V1_BASE_SIZE), buffOffset);
    buffOffset += V1_BASE_SIZE * sizeof(P);
    hMixBuff_ = tmpBuff_.GetWithOffset<P>(uint32_t(V1_BASE_SIZE * matrixInfo_.fusionSize), buffOffset);
}

template <class T, class P>
__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPreSplitNDKernel<T, P>::Process()
{
    // 实现核心计算逻辑
    if ASCEND_IS_AIV {
        vecCoreIdx_ = GetBlockIdx();
        coreIdx_ = vecCoreIdx_ / 2;
        V0VectorComputeProcess();
        AIVPreLoad();
    }
    if ASCEND_IS_AIC {
        AICProcess();
    }
    SyncAll<false>();
    if ASCEND_IS_AIV {
        AIV1Process();
        biasInQue_.FreeTensor(biasInUb_);
    }
}

template <class T, class P>
__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPreSplitNDKernel<T, P>::AIV1GetHSliceOffset()
{
    uint32_t offset1 = 0;
    uint32_t offset2 = 0;
    uint32_t offset3 = 0;
    uint32_t curOffset = 0;
    uint32_t nSquare = N_ * N_;
    for (uint32_t i = 0; i < V1_BASE_SIZE; i++) {
        for (uint32_t j = 0; j < N_; j++) {
            preOffsetBuf_.SetValue(offset1++, curOffset * sizeof(P));
            curOffset++;
        }
        for (uint32_t j = 0; j < N_; j++) {
            postOffsetBuf_.SetValue(offset2++, curOffset * sizeof(P));
            curOffset++;
        }
        for (uint32_t j = 0; j < nSquare; j++) {
            resOffsetBuf_.SetValue(offset3++, curOffset * sizeof(P));
            curOffset++;
        }
    }
}

template <class T, class P>
__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPreSplitNDKernel<T, P>::AICProcess()
{
    uint64_t outOffset = mnConfig_.m * mnConfig_.n * coreIdx_;

    mnConfig_.curSingleCoreK = Ceil(matrixInfo_.nD, c0UsedCoreNum_);
    if(mnConfig_.curSingleCoreK * coreIdx_ >= matrixInfo_.nD){
        return;
    }
    uint64_t xOffset = mnConfig_.curSingleCoreK * coreIdx_;
    uint64_t phiOffset = mnConfig_.curSingleCoreK * coreIdx_;
    if(mnConfig_.curSingleCoreK * coreIdx_ + mnConfig_.curSingleCoreK > matrixInfo_.nD){
        mnConfig_.curSingleCoreK = matrixInfo_.nD - mnConfig_.curSingleCoreK * coreIdx_;
    }
    AscendC::CrossCoreWaitFlag(SYNC_V2C);
    mm.SetOrgShape(mnConfig_.m, mnConfig_.n, mnConfig_.k);                       // MNK
    mm.SetSingleShape(mnConfig_.m, mnConfig_.n, mnConfig_.curSingleCoreK); // SingleCoreMNK
    mm.SetTensorA(xFloatGm_[xOffset]);
    mm.SetTensorB(phiGm_[phiOffset], true);
    mm.IterateAll(mmResGm_[outOffset]);
    mm.End();
}

template <class T, class P>
__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPreSplitNDKernel<T, P>::VectorComputeOffset()
{
    curSingleM_ = Ceil(totalLength_, coreNum_ * 2);
    vectorOffset_.offsetMStart = curSingleM_ * vecCoreIdx_;
    vectorOffset_.offsetMEnd = vectorOffset_.offsetMStart + curSingleM_ > totalLength_ ? 
                               totalLength_ : vectorOffset_.offsetMStart + curSingleM_;
    vectorOffset_.singleCoreM = vectorOffset_.offsetMEnd - vectorOffset_.offsetMStart;
}

template <class T, class P>
__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPreSplitNDKernel<T, P>::VectorComputeOffsetV0()
{
    curSingleK_ = Ceil(matrixInfo_.nD, c0UsedCoreNum_);
    uint64_t aliginSingleK = Ceil(curSingleK_ / 2, 8) * 8; // 32Byte对齐
    vectorOffset_.singleCoreK = aliginSingleK <  curSingleK_ ? aliginSingleK : curSingleK_;
    if (subBlockIdx_ == 0) {
        vectorOffset_.offsetK = curSingleK_ * coreIdx_;
    } else {
        vectorOffset_.offsetK = curSingleK_ * coreIdx_ + aliginSingleK;
        vectorOffset_.singleCoreK = curSingleK_ - vectorOffset_.singleCoreK;
    }
}

template <class T, class P>
__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPreSplitNDKernel<T, P>::V0VectorComputeProcess()
{
    curSingleM_= totalLength_;
    VectorComputeOffsetV0(); // 计算0核和1核的偏移

    if (vectorOffset_.offsetK > matrixInfo_.nD || vectorOffset_.singleCoreK <= 0) {
        CrossCoreSetFlag<0x2, PIPE_MTE3>(SYNC_V2C);
        return;
    }

    uint64_t computeLen = curSingleM_ * vectorOffset_.singleCoreK;
    uint64_t curNdLen = vectorOffset_.singleCoreK;
    if (vectorOffset_.offsetK + vectorOffset_.singleCoreK >= matrixInfo_.nD) {
        curNdLen = matrixInfo_.nD - vectorOffset_.offsetK;
    }
    for (uint64_t offsetT = 0; offsetT < totalLength_; offsetT += v0ChunkTSize_) {
        uint32_t curMLen = offsetT + v0ChunkTSize_ < totalLength_ ? v0ChunkTSize_ : totalLength_ - offsetT;
        computeLen = curMLen * Ceil(curNdLen, 16) * 16;
        // copy x
        xLocal_ = xInQueue_.AllocTensor<T>();
        DataCopyX(curMLen, curNdLen, offsetT, vectorOffset_.offsetK);
        xLocal_ = xInQueue_.DeQue<T>();

        // bf16转fp32
        xFp32Ub_ = outQueue_.AllocTensor<P>();
        Cast(xFp32Ub_, xLocal_, AscendC::RoundMode::CAST_NONE, computeLen);
        PipeBarrier<PIPE_V>();
        Mul(mulFp32Ub_, xFp32Ub_, xFp32Ub_, computeLen);

        PipeBarrier<PIPE_V>();
        DataCopyOutToWorkSpace(curMLen, curNdLen, offsetT, vectorOffset_.offsetK);
        PipeBarrier<PIPE_V>();
        uint32_t srcShape[2] = {curMLen, Ceil(curNdLen, 16) * 16};
        invRmsUb_ = invRmsOutQueue_.AllocTensor<P>();
        ReduceSum<float, AscendC::Pattern::Reduce::AR, true>(invRmsUb_, mulFp32Ub_, srcShape, true);
        DataCopyOutInvRmsUb(curMLen, offsetT);
        xInQueue_.FreeTensor(xLocal_);
        outQueue_.FreeTensor(xFp32Ub_);
        invRmsOutQueue_.FreeTensor(invRmsUb_);
    }
    CrossCoreSetFlag<0x2, PIPE_MTE3>(SYNC_V2C);
}

template <class T, class P>
__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPreSplitNDKernel<T, P>::AIV1Process()
{
    VectorComputeOffset(); // 计算0核和1核的偏移
    if (vectorOffset_.singleCoreM <= 0) {
        return;
    }
    uint64_t lenT = 0;
    uint64_t lenD = 0;
    uint64_t singleCoreOffset = 0;
    for (int offsetT = vectorOffset_.offsetMStart; offsetT < vectorOffset_.offsetMEnd; offsetT += V1_BASE_SIZE) {
        lenT = V1_BASE_SIZE < vectorOffset_.offsetMEnd - offsetT ? V1_BASE_SIZE : vectorOffset_.offsetMEnd - offsetT;
        lenD = v1ChunkDSize_;
        // H 切分
        AIV1Prologue(offsetT, lenT, singleCoreOffset);
        AIV1ProcessHPost(offsetT, lenT);
        AIV1ProcessHPre(offsetT, lenT);
        auto hInDealBuf = inputBuff_; // 最大80K
        auto reduceResult = hInDealBuf[lenD * N_]; // 最大10K
        PipeBarrier<PIPE_ALL>();
        for (uint32_t tIdx = 0; tIdx < lenT; tIdx++) {
            for (int offsetD = 0; offsetD < D_; offsetD += v1ChunkDSize_) {
                lenD = v1ChunkDSize_ < D_ - offsetD ? v1ChunkDSize_ : D_ - offsetD;
                uint32_t ubOffset = 0;
                const uint32_t srcReduceShape_[2] = {static_cast<uint32_t>(N_), static_cast<uint32_t>(lenD)};
                for (uint32_t nIdx = 0; nIdx < N_; nIdx++) {
                    uint64_t xGmOffset = (globalOffsetM_ + offsetT + tIdx) * N_ * D_ + nIdx * D_ + offsetD;

                    LocalTensor<T> xIn = xInQueue_.AllocTensor<T>();
                    // copy X
                    DataCopyExtParams copyParams;
                    copyParams.blockCount = static_cast<uint16_t>(1);
                    copyParams.blockLen = uint32_t(lenD * sizeof(T));
                    copyParams.srcStride = 0;
                    copyParams.dstStride = 0;

                    uint32_t rightPadNum = Ceil(lenD, 16) * 16 - lenD;
                    DataCopyPadExtParams<T> padParams{true, 0, static_cast<uint8_t>(rightPadNum), 0};
                    DataCopyPad(xIn, xGm_[xGmOffset], copyParams, padParams);

                    xInQueue_.EnQue(xIn);
                    xIn = xInQueue_.DeQue<T>();

                    Cast(hInDealBuf[ubOffset], xIn, RoundMode::CAST_NONE, lenD);
                    PipeBarrier<PIPE_V>();
                    xInQueue_.FreeTensor(xIn);

                    Muls(hInDealBuf[ubOffset], hInDealBuf[ubOffset], hPreBuff_.GetValue(tIdx * N_ + nIdx), lenD);
                    PipeBarrier<PIPE_V>();
                    ubOffset += lenD;
                }

                // reducesum 
                ReduceSum<P, Pattern::Reduce::RA, true>(reduceResult, hInDealBuf, srcReduceShape_, true);
                PipeBarrier<PIPE_V>();

                // cast
                LocalTensor<T> hinOut = outQueue_.AllocTensor<T>();
                Cast(hinOut, reduceResult, RoundMode::CAST_RINT, lenD);
                PipeBarrier<PIPE_V>();

                outQueue_.EnQue(hinOut);
                hinOut = outQueue_.DeQue<T>();
                // copyout
                DataCopyExtParams copyParams;
                copyParams.blockCount = 1; // 行数
                copyParams.blockLen = uint32_t(lenD * sizeof(T));
                copyParams.srcStride = 0;
                copyParams.dstStride = 0;

                DataCopyPad(hinGm_[(globalOffsetM_ + offsetT + tIdx) * D_ + offsetD], hinOut, copyParams);
                PipeBarrier<PIPE_V>();
                outQueue_.FreeTensor(hinOut);
            }
        }
    }
}

template <class T, class P>
__aicore__ inline void
AiInfraManifoldConstrainedHyperConnectionPreSplitNDKernel<T, P>::AIV1Prologue(uint64_t offsetT, uint64_t lenT,
                                                                              uint64_t singleCoreOffset)
{
    LocalTensor<P> hResOutLocal = outQueue_.AllocTensor<P>();
    uint64_t HMixOffset = 0;
    HMixOffset = offsetT * mnConfig_.n;
    InvRmsCopyIn(offsetT, lenT);
    LocalTensor<P> invRmsInLocal = xInQueue_.DeQue<P>(); 
    uint32_t srcShape[] = {uint32_t(c0UsedCoreNum_ * 2), uint32_t(Ceil(lenT, 8) * 8)};
    ReduceSum<P, Pattern::Reduce::RA, true>(invRmsBuff_, invRmsInLocal, srcShape, true);
    xInQueue_.FreeTensor(invRmsInLocal);
    PipeBarrier<PIPE_V>();
    Muls(invRmsBuff_, invRmsBuff_, scaleMean_, lenT);
    PipeBarrier<PIPE_V>();

    Adds(invRmsBuff_, invRmsBuff_, matrixInfo_.normEps, lenT);
    PipeBarrier<PIPE_V>();

    Sqrt(invRmsBuff_, invRmsBuff_, lenT);
    PipeBarrier<PIPE_V>();
    Div(invRmsBuff_, oneUb_, invRmsBuff_, lenT);
    PipeBarrier<PIPE_V>();

    uint32_t hMixShape[] = {uint32_t(lenT), uint32_t(mnConfig_.n)};
    uint32_t alphaBiaShape[] = {uint32_t(1), uint32_t(mnConfig_.n)};
    uint32_t rShape[] = {uint32_t(lenT), uint32_t(1)};
    HMixCopyIn(HMixOffset, lenT);
    matmulRes_ = xInQueue_.DeQue<P>(); 
    srcShape[0] = uint32_t(c0UsedCoreNum_);
    srcShape[1] = uint32_t(lenT * matrixInfo_.fusionSize);
    ReduceSum<P, Pattern::Reduce::RA, true>(hMixBuff_, matmulRes_, srcShape, true);
    xInQueue_.FreeTensor(matmulRes_);

    Broadcast<P, 2, 1>(broadCastTmpUb_, invRmsBuff_, hMixShape, rShape);
    pipe_barrier(PIPE_V);
    hMixBuff_ = hMixBuff_ * broadCastTmpUb_;
    pipe_barrier(PIPE_V);
    Broadcast<P, 2, 0>(broadCastTmpUb_, alphaInUb_, hMixShape, alphaBiaShape);
    pipe_barrier(PIPE_V);
    hMixBuff_ = hMixBuff_ * broadCastTmpUb_;
    pipe_barrier(PIPE_V);
    Broadcast<P, 2, 0>(broadCastTmpUb_, biasInUb_, hMixShape, alphaBiaShape);
    pipe_barrier(PIPE_V);
    hMixBuff_ = hMixBuff_ + broadCastTmpUb_;
    pipe_barrier(PIPE_V);

    SetFlag<HardEvent::MTE2_V>(EVENT_ID1);
    WaitFlag<HardEvent::MTE2_V>(EVENT_ID1);

    Gather(hPreBuff_, hMixBuff_, preOffsetBuf_, uint32_t(0), lenT * N_);
    Gather(hPostBuff_, hMixBuff_, postOffsetBuf_, uint32_t(0), lenT * N_);
    Gather(hResOutLocal, hMixBuff_, resOffsetBuf_, uint32_t(0), lenT * N_ * N_);
    PipeBarrier<PIPE_V>();
    outQueue_.EnQue(hResOutLocal);
    hResOutLocal = outQueue_.DeQue<P>();
    DataCopyExtParams copyParams;
    copyParams.blockCount = static_cast<uint16_t>(1);
    copyParams.blockLen = uint32_t(lenT * N_ * N_ * sizeof(P));
    copyParams.srcStride = uint32_t(0);
    copyParams.dstStride = uint32_t(0);
    DataCopyPad(hResGm_[offsetT * N_ * N_], hResOutLocal, copyParams);
    outQueue_.FreeTensor(hResOutLocal);
}

template <class T, class P>
__aicore__ inline void
AiInfraManifoldConstrainedHyperConnectionPreSplitNDKernel<T, P>::AIV1ProcessHPre(uint64_t offsetT, uint64_t lenT)
{
    uint64_t offset = globalOffsetM_ + offsetT;
    LocalTensor<P> hPreSigmoid = inputBuff_;

    Sigmoid(hPreSigmoid, hPreBuff_, lenT * N_);
    PipeBarrier<PIPE_V>();
    Adds(hPreBuff_, hPreSigmoid, matrixInfo_.hcEps, lenT * N_);
    PipeBarrier<PIPE_V>();
}

template <class T, class P>
__aicore__ inline void
AiInfraManifoldConstrainedHyperConnectionPreSplitNDKernel<T, P>::AIV1ProcessHPost(uint64_t offsetT, uint64_t lenT)
{
    uint64_t offset = globalOffsetM_ + offsetT;
    LocalTensor<P> hPostSigmoid = broadCastTmpUb_;
    LocalTensor<P> hPostOutLocal = outQueue_.AllocTensor<P>();
    Sigmoid(hPostSigmoid, hPostBuff_);
    PipeBarrier<PIPE_V>();
    Muls(hPostOutLocal, hPostSigmoid, static_cast<float>(2.0), lenT * N_);
    PipeBarrier<PIPE_V>();
    outQueue_.EnQue(hPostOutLocal);
    hPostOutLocal = outQueue_.DeQue<P>();
    DataCopyExtParams copyParams;
    copyParams.blockCount = static_cast<uint16_t>(1);
    copyParams.blockLen = uint32_t(lenT * N_ * sizeof(P));
    copyParams.srcStride = uint32_t(0);
    copyParams.dstStride = uint32_t(0);
    DataCopyPad(hPostGm_[offset * N_], hPostOutLocal, copyParams);
    outQueue_.FreeTensor(hPostOutLocal);
}

template <class T, class P>
__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPreSplitNDKernel<T, P>::AIVPreLoad()
{
    AIV1GetHSliceOffset();
    float alphaPre = alphaGm_.GetValue(0);
    float alphaPost = alphaGm_.GetValue(1);
    float alphaComb = alphaGm_.GetValue(2);
    for(uint64_t i = 0; i < N_; ++i){
        alphaInUb_.SetValue(i, alphaPre);
        alphaInUb_.SetValue(i + N_, alphaPost);
        for(uint64_t j = 0; j < N_; ++j){
            alphaInUb_.SetValue((2 + i) * N_ + j, alphaComb);
        }
    }
    BiasCopyIn();
    biasInUb_ = biasInQue_.DeQue<P>();
}

template <class T, class P>
__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPreSplitNDKernel<T, P>::BiasCopyIn()
{
    LocalTensor<P> biasLocal = biasInQue_.AllocTensor<P>();
    DataCopyExtParams copyParams;
    copyParams.blockCount = static_cast<uint16_t>(1); // 行数
    copyParams.blockLen = uint32_t(matrixInfo_.fusionSize * sizeof(P));
    copyParams.srcStride = uint32_t(0); // 相邻块的间隔
    copyParams.dstStride = uint32_t(0);                                                   // 相邻块的间隔
    DataCopyPadExtParams<P> copyPadParams{true, 0, 0, 0};

    DataCopyPad(biasLocal, biasGm_, copyParams, copyPadParams);
    biasInQue_.EnQue(biasLocal);
}

template <class T, class P>
__aicore__ inline void
AiInfraManifoldConstrainedHyperConnectionPreSplitNDKernel<T, P>::DataCopyX(uint32_t curMLen, uint32_t curNdLen,
                                                                           uint32_t offsetT, uint32_t offsetNd)
{
    DataCopyExtParams copyParams;
    copyParams.blockCount = static_cast<uint16_t>(curMLen);
    copyParams.blockLen = uint32_t(curNdLen * sizeof(T));
    copyParams.srcStride = uint32_t((matrixInfo_.nD - curNdLen) * sizeof(T));
    copyParams.dstStride = uint32_t(0);
    uint32_t rightPadNum = Ceil(curNdLen, 16) * 16 - curNdLen;
    DataCopyPadExtParams<T> padParams{true, 0, static_cast<uint8_t>(rightPadNum), 0};

    uint64_t offset = offsetT * matrixInfo_.nD + offsetNd;
    DataCopyPad(xLocal_, xGm_[offset], copyParams, padParams);
    xInQueue_.EnQue<T>(xLocal_);
}

template <class T, class P>
__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPreSplitNDKernel<T, P>::HMixCopyIn(uint64_t offset,
                                                                                                   uint64_t lenT)
{
    LocalTensor<P> hMixLocal = xInQueue_.AllocTensor<P>();
    DataCopyExtParams copyParams;
    copyParams.blockCount = static_cast<uint16_t>(c0UsedCoreNum_); // 行数
    copyParams.blockLen = uint32_t(lenT * mnConfig_.n * sizeof(P));
    copyParams.srcStride = uint32_t((totalLength_ - lenT) * mnConfig_.n * sizeof(P)); // 相邻块的间隔
    copyParams.dstStride = uint32_t(0);                                                   // 相邻块的间隔
    DataCopyPadExtParams<P> copyPadParams{true, 0, 0, 0};

    DataCopyPad(hMixLocal, mmResGm_[offset], copyParams, copyPadParams);
    xInQueue_.EnQue(hMixLocal);
}

template <class T, class P>
__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPreSplitNDKernel<T, P>::InvRmsCopyIn(uint64_t offsetT,
                                                                                                     uint32_t lenT)
{
    LocalTensor<P> invRmsInLocal = xInQueue_.AllocTensor<P>();
    DataCopyExtParams copyParams;
    copyParams.blockCount = static_cast<uint16_t>(c0UsedCoreNum_ * 2); // 行数
    copyParams.blockLen = uint32_t(lenT * sizeof(P));
    copyParams.srcStride = uint32_t((totalLength_ - lenT) * sizeof(P)); // 相邻块的间隔
    copyParams.dstStride = uint32_t(0);                                                   // 相邻块的间隔
    DataCopyPadExtParams<P> copyPadParams{true, 0, 0, 0};

    DataCopyPad(invRmsInLocal, invRmsGm_[offsetT], copyParams, copyPadParams);
    xInQueue_.EnQue(invRmsInLocal);
}

template <class T, class P>
__aicore__ inline void
AiInfraManifoldConstrainedHyperConnectionPreSplitNDKernel<T, P>::DataCopyOutInvRmsUb(uint32_t curMLen, uint32_t offsetT)
{
    invRmsOutQueue_.EnQue<P>(invRmsUb_);
    invRmsUb_ = invRmsOutQueue_.DeQue<P>();

    DataCopyExtParams copyParams;
    copyParams.blockCount = static_cast<uint16_t>(1);
    copyParams.blockLen = uint32_t(curMLen * sizeof(P));
    copyParams.srcStride = uint32_t(0);
    copyParams.dstStride = uint32_t(0);

    uint64_t offset = (coreIdx_ * 2 + subBlockIdx_) * totalLength_ + offsetT;
    DataCopyPad(invRmsGm_[offset], invRmsUb_, copyParams);
}

template <class T, class P>
__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPreSplitNDKernel<T, P>::DataCopyOutToWorkSpace(
    uint32_t curMLen, uint32_t curNdLen, uint32_t offsetT, uint32_t offsetNd)
{
    uint32_t aliginNdStride = 0;
    if (curNdLen % 16 <= 8 && curNdLen % 16 > 0) { // curNdLen对16取余大于0且小于8时，srcStride需为1.
        aliginNdStride = 1;
    }

    outQueue_.EnQue<P>(xFp32Ub_);
    xFp32Ub_ = outQueue_.DeQue<P>();

    DataCopyExtParams copyParams;
    copyParams.blockCount = static_cast<uint16_t>(curMLen);
    copyParams.blockLen = uint32_t(curNdLen * sizeof(P));
    copyParams.srcStride = uint32_t(aliginNdStride);
    copyParams.dstStride = uint32_t((matrixInfo_.nD - curNdLen) * sizeof(P));

    uint64_t offset = offsetT * matrixInfo_.nD + offsetNd;
    DataCopyPad(xFloatGm_[offset], xFp32Ub_, copyParams);
}

