22	
23	extern "C" __global__ __aicore__ void
24	ai_infra_manifold_constrained_hyper_connection_pre(GM_ADDR x, GM_ADDR phi, GM_ADDR alpha, GM_ADDR bias, GM_ADDR gamma,
25	                                                   GM_ADDR hin, GM_ADDR h_post, GM_ADDR h_res, GM_ADDR inv_rms,
