#include "ai_infra_manifold_constrained_hyper_connection_pre.h"
#include "ai_infra_manifold_constrained_hyper_connection_pre_split_ND.h"

using namespace AscendC;
using namespace matmul;
using namespace AiInfraManifoldConstrainedHyperConnectionPre;

extern "C" __global__ __aicore__ void
ai_infra_manifold_constrained_hyper_connection_pre(GM_ADDR x, GM_ADDR phi, GM_ADDR alpha, GM_ADDR bias, GM_ADDR gamma,
                                                   GM_ADDR hin, GM_ADDR h_post, GM_ADDR h_res, GM_ADDR inv_rms,
                                                   GM_ADDR mm_res, GM_ADDR h_pre, GM_ADDR workspaceGM, GM_ADDR tilingGM)
{
    GET_TILING_DATA(tilingData, tilingGM);
    __gm__ uint8_t *user = GetUserWorkspace(workspaceGM);

    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIC_1_2);
    TPipe pipe;
    InitParams initParams{x,     phi,     alpha,  bias,  gamma, hin,   h_post,
                          h_res, inv_rms, mm_res, h_pre, user,  &pipe, &tilingData};
    if (TILING_KEY_IS(0UL)) {
        MT mm;
        mm.Init(&tilingData.matmulTiling, &pipe);
        AiInfraManifoldConstrainedHyperConnectionPreKernel<DTYPE_X, float32_t> op(mm);
        op.Init(initParams);
        op.Process();
    }
    if (TILING_KEY_IS(1UL)) {
        MT mm;
        mm.Init(&tilingData.matmulTiling, &pipe);
        AiInfraManifoldConstrainedHyperConnectionPreSplitNDKernel<DTYPE_X, float32_t> op(mm);
        op.Init(initParams);
        op.Process();
    }
}

