90	static constexpr uint64_t SYNC_C2V = 0x2;      // Cube→Vector同步标志
91	static constexpr uint64_t SYNC_C2V1 = 0x3;    // Cube→Vector同步标志1
92	
93	// 其他常量
94	static constexpr uint32_t parallNum_ = 2;     // 并行数量
95	
96	using aT = MatmulType<TPosition::GM, CubeFormat::ND, float32_t>;
97	using bT = MatmulType<TPosition::GM, CubeFormat::ND, float32_t, true>;
98	using cT = MatmulType<TPosition::GM, CubeFormat::ND, float32_t>;
99	using MT = matmul::MatmulImpl<aT, bT, cT>;
100	
101	template <class T, class P>
102	class AiInfraManifoldConstrainedHyperConnectionPreKernel {
103	public:
104	    __aicore__ inline AiInfraManifoldConstrainedHyperConnectionPreKernel(MT &matmul) : mm(matmul) {}
105	    __aicore__ inline void Init(InitParams initParams);
106	    __aicore__ inline void Process();
107	    __aicore__ inline void AICProcess();
108	    __aicore__ inline void InitLocalBuffers();
109	    __aicore__ inline void VectorComputeOffset();
110	    __aicore__ inline void V0VectorComputeProcess(uint32_t curblock, uint32_t tblockNum);
111	    __aicore__ inline void DataCopyX(uint32_t curMLen, uint32_t curNdLen, uint32_t offsetM, uint32_t offsetNd);
112	    __aicore__ inline void DataCopyOutInvRmsUb(uint32_t curMLen, uint32_t offsetM);
113	    __aicore__ inline void DataCopyOutToWorkSpace(uint32_t curMLen, uint32_t curNdLen, uint32_t offsetM,
114	                                                  uint32_t offsetNd);
115	    __aicore__ inline void DataCopyGamma(uint32_t curNdLen, uint32_t offsetNd);
116	    __aicore__ inline void AIVPreLoad();
117	    __aicore__ inline void HMixCopyIn(uint64_t offset, uint64_t lenT);
118	    __aicore__ inline void AIV1ProcessHPost(uint64_t offsetT, uint64_t lenT, uint64_t lenD);
119	    __aicore__ inline void AIV1ProcessHPre(uint64_t offsetT, uint64_t lenT);
120	    __aicore__ inline void AIV1Prologue(uint64_t offsetT, uint64_t lenT, uint64_t singleCoreOffset);
121	    __aicore__ inline void AIV1Process(uint64_t curBlock, uint64_t tBlockNum);
122	    __aicore__ inline void BiasCopyIn();
123	    __aicore__ inline void AIV1GetHSliceOffset();
124	private:
125	    MT &mm;
126	    MNConfig mnConfig_;
127	    uint32_t coreNum_;
128	    uint64_t totalLength_;
129	    uint64_t N_;
130	    uint64_t D_;
131	    bool outFlag_;
132	    bool hasGamma_;
133	
134	    GlobalTensor<T> xGm_;      // 输入 x
135	    GlobalTensor<P> phiGm_;    // 输入 phi
136	    GlobalTensor<P> alphaGm_;  // 输入 alpha
137	    GlobalTensor<P> biasGm_;   // 输入 bias
138	    GlobalTensor<P> gammaGm_;   // 输入 gamma
139	    GlobalTensor<T> hinGm_;    // 输出 hin
140	    GlobalTensor<P> hPostGm_;  // 输出 h_post
141	    GlobalTensor<P> hResGm_;   // 输出 h_res
142	    GlobalTensor<P> invRmsGm_;   // 输出 h_res
143	    GlobalTensor<P> mmResGm_;   // 输出 h_res
144	    GlobalTensor<P> hPreGm_;   // 输出 h_res
145	    GlobalTensor<P> xFloatGm_;
146	
147	    TQue<QuePosition::VECIN, 1> xInQueue_;
148	    TQue<QuePosition::VECIN, 1> biasQueue_;
149	    TQue<QuePosition::VECIN, 1> gammaInQueue_;
150	    TQue<QuePosition::VECOUT, 1> invRmsOutQueue_;
151	    TQue<QuePosition::VECOUT, 1> outQueue_;
152	    TQue<QuePosition::VECIN, 1> biasInQue_;
153	
154	    TBuf<TPosition::VECCALC> tmpBuff_;
155	    TBuf<TPosition::VECCALC> alphaBuf_;
156	
157	    LocalTensor<P> inputBuff_;
158	    LocalTensor<P> hPreBuff_;
159	    LocalTensor<P> hPreBrcb_;
160	    LocalTensor<P> hPostBuff_;
161	    LocalTensor<P> hResBuff_;
162	    LocalTensor<uint8_t> brcbBuff_;
163	
164	    LocalTensor<P> alphaInUb_;
165	    LocalTensor<P> biasInUb_;
166	    LocalTensor<P> broadCastTmpUb_;
167	    LocalTensor<P> matmulRes_;
168	
169	    LocalTensor<T> xLocal_;
170	    LocalTensor<P> invRmsUb_;
171	    LocalTensor<P> gammaUb_;
172	    LocalTensor<P> xFp32Ub_;
173	    LocalTensor<P> gammaXFp32Ub_;
174	
175	    LocalTensor<uint32_t> preOffsetBuf_;
176	    LocalTensor<uint32_t> postOffsetBuf_;
177	    LocalTensor<uint32_t> resOffsetBuf_;
178	
179	    LocalTensor<P> mulFp32Ub_;
180	    LocalTensor<P> sumFp32Ub_;
181	    LocalTensor<P> oneUb_;
182	
183	    TPipe *pipe_;
184	    MatrixInfo matrixInfo_;
185	    VectorOffsetParams vectorOffset_;
186	
187	    const AiInfraManifoldConstrainedHyperConnectionPreTilingData *tiling_;
188	    
189	    // 运行时状态变量
190	    uint32_t chunTSize_ = 192;
191	    uint32_t v1ChunkDSize_ = 5120;
192	    uint32_t curSingleM_ = 192;  // 当前块的实际大小（可能小于singleM_，如果是最后一个块）
193	    uint32_t coreIdx_ = 0;
194	    uint32_t subBlockIdx_ = 0;
195	    float scaleMean_ = 0.0f; // 1/nD
196	    uint64_t globalOffsetM_ = 0;
197	    uint32_t vectorCount_ = 0;
198	    uint32_t cubeCount_ = 0;
199	    uint64_t mmCount_ = 0;
200	    uint64_t vec1Count_ = 0;
201	};
202	
203	template <class T, class P>
204	__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPreKernel<T, P>::Init(InitParams initParams)
205	{
206	    // 1. 绑定GlobalTensor
207	    xGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(initParams.x));
208	    phiGm_.SetGlobalBuffer(reinterpret_cast<__gm__ P *>(initParams.phi));
209	    alphaGm_.SetGlobalBuffer(reinterpret_cast<__gm__ P *>(initParams.alpha));
210	    biasGm_.SetGlobalBuffer(reinterpret_cast<__gm__ P *>(initParams.bias));
211	    gammaGm_.SetGlobalBuffer(reinterpret_cast<__gm__ P *>(initParams.gamma));
212	    hinGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(initParams.hin));
213	    hPostGm_.SetGlobalBuffer(reinterpret_cast<__gm__ P *>(initParams.h_post));
214	    hResGm_.SetGlobalBuffer(reinterpret_cast<__gm__ P *>(initParams.h_res));
215	
216	    invRmsGm_.SetGlobalBuffer(reinterpret_cast<__gm__ P *>(initParams.inv_rms));
217	    hPreGm_.SetGlobalBuffer(reinterpret_cast<__gm__ P *>(initParams.h_pre)); 
218	
219	    xFloatGm_.SetGlobalBuffer(reinterpret_cast<__gm__ P *>(initParams.workspace));
220	
221	    // 2. 获取TilingData进行初始化
222	    tiling_ = initParams.tilingData;
223	    matrixInfo_.totalLength = tiling_->totalLength;
224	    matrixInfo_.nD = tiling_->nD;
225	
226	    N_ = tiling_->N;
227	    D_ = tiling_->D;
228	    matrixInfo_.fusionSize = tiling_->fusionSize;
229	    matrixInfo_.normEps = tiling_->normEps;
230	    matrixInfo_.hcEps = tiling_->hcEps;
231	    coreNum_ = tiling_->coreNum;
232	    totalLength_ = tiling_->totalLength;
233	    outFlag_ = (tiling_->outFlag != 0);
234	    scaleMean_ = tiling_->scaleMean;
235	    chunTSize_ = tiling_->chunkTSize;
236	    v1ChunkDSize_ = tiling_->v1ChunkDSize;
237	    hasGamma_ = (tiling_->hasGamma != 0);
238	
239	    mnConfig_.m = matrixInfo_.totalLength;
240	    mnConfig_.n = matrixInfo_.fusionSize;
241	    mnConfig_.k = matrixInfo_.nD;
242	    mnConfig_.singleCoreM = chunTSize_;
243	    mnConfig_.singleCoreN = mnConfig_.n;
244	    mnConfig_.singleCoreK = 256;
245	    mnConfig_.curSingleCoreM = mnConfig_.singleCoreM;
246	    mnConfig_.curSingleCoreN = mnConfig_.singleCoreN;
247	    mnConfig_.curSingleCoreK = mnConfig_.singleCoreK;
248	    curSingleM_ = chunTSize_;
249	
250	    if (outFlag_) {
251	        mmResGm_.SetGlobalBuffer(reinterpret_cast<__gm__ P *>(initParams.mm_res));
252	    }
253	    else {
254	        mmResGm_.SetGlobalBuffer(reinterpret_cast<__gm__ P *>(
255	            initParams.workspace + mnConfig_.singleCoreM * mnConfig_.singleCoreK * parallNum_ * sizeof(P) * coreNum_));
256	    }
257	
258	    // 3. 申请UB
259	    pipe_ = initParams.tPipeIn;
260	    coreIdx_ = GetBlockIdx();
261	    subBlockIdx_ = GetSubBlockIdx();
262	
263	    if ASCEND_IS_AIV {
264	        InitLocalBuffers();
265	        Duplicate<float>(oneUb_, 1.0f, curSingleM_ / 2); // 全为1的tensor，用于计算倒数
266	    }
267	    
268	    SyncAll();
269	}
270	
271	
272	template <class T, class P>
273	__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPreKernel<T, P>::InitLocalBuffers()
274	{
275	    pipe_->InitBuffer(xInQueue_, 2, 20 * 1024); // 20KB
276	    pipe_->InitBuffer(outQueue_, 2, 20 * 1024); // 32KB
277	    pipe_->InitBuffer(invRmsOutQueue_, 1, (curSingleM_ / 2) * sizeof(P)); // 1KB
278	
279	    if (hasGamma_) {
280	        pipe_->InitBuffer(gammaInQueue_, 1, ND_LENGTH * sizeof(P)); // 1KB
281	    }
282	    
283	    pipe_->InitBuffer(tmpBuff_, 105 * 1024); // 120KB
284	
285	    pipe_->InitBuffer(biasInQue_, 1, mnConfig_.n * sizeof(P)); // 1KB
286	    pipe_->InitBuffer(alphaBuf_, mnConfig_.n * sizeof(P)); // 1KB
287	    alphaInUb_ = alphaBuf_.Get<P>();
288	
289	    preOffsetBuf_ = tmpBuff_.GetWithOffset<uint32_t>(uint32_t(mnConfig_.n * V1_BASE_T), 0);
290	    postOffsetBuf_ = preOffsetBuf_[N_ * V1_BASE_T];
291	    resOffsetBuf_ = postOffsetBuf_[N_ * V1_BASE_T];
292	    uint64_t buffOffset = mnConfig_.n * V1_BASE_T * sizeof(uint32_t);
293	    oneUb_ = tmpBuff_.GetWithOffset<P>(uint32_t(curSingleM_ / 2), buffOffset);
294	
295	    // V0
296	    buffOffset = mnConfig_.n * V1_BASE_T * sizeof(uint32_t) + (curSingleM_ / 2) * sizeof(uint32_t);
297	    mulFp32Ub_ = tmpBuff_.GetWithOffset<P>(uint32_t(V0_BASE_T * ND_LENGTH), buffOffset);
298	    buffOffset += V0_BASE_T * ND_LENGTH * sizeof(P);
299	    gammaXFp32Ub_ = tmpBuff_.GetWithOffset<P>(uint32_t(V0_BASE_T * ND_LENGTH), buffOffset);
300	    buffOffset += V0_BASE_T * ND_LENGTH * sizeof(P);
301	    sumFp32Ub_ = tmpBuff_.GetWithOffset<P>(uint32_t(V0_BASE_T), buffOffset);
302	    
303	    // V1
304	    buffOffset = mnConfig_.n * V1_BASE_T * sizeof(uint32_t) + (curSingleM_ / 2) * sizeof(uint32_t);
305	    hPreBuff_ = tmpBuff_.GetWithOffset<P>(uint32_t(V1_BASE_T * N_), buffOffset);
306	    buffOffset += V1_BASE_T * N_ * sizeof(P);
307	    inputBuff_ = tmpBuff_.GetWithOffset<P>(uint32_t(mnConfig_.n * V1_BASE_T * V1_BASE_D), buffOffset);
308	    buffOffset += mnConfig_.n * V1_BASE_T * sizeof(P);
309	    broadCastTmpUb_ = tmpBuff_.GetWithOffset<P>(uint32_t(mnConfig_.n * V1_BASE_T), buffOffset); // 20KB
310	    buffOffset += mnConfig_.n * V1_BASE_T * sizeof(P);
311	    hPostBuff_ = tmpBuff_.GetWithOffset<P>(uint32_t(V1_BASE_T * N_), buffOffset);
312	    buffOffset += V1_BASE_T * N_ * sizeof(P);
313	    hResBuff_ = tmpBuff_.GetWithOffset<P>(uint32_t(V1_BASE_T * N_), buffOffset);
314	    buffOffset += V1_BASE_T * N_ * sizeof(P);
315	}
316	
317	template <class T, class P>
318	__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPreKernel<T, P>::Process()
319	{
320	    // 实现核心计算逻辑
321	    // 根据tiling数据进行分块处理
322	    uint32_t tBlockNum = Ceil(totalLength_, chunTSize_);
323	    if ASCEND_IS_AIV {
324	        coreIdx_ = GetBlockIdx() / 2;
325	        AIVPreLoad();
326	    }
327	    
328	    for (uint64_t offset = coreIdx_; offset < tBlockNum; offset += coreNum_) {
329	        // 处理每个batch/sequence的数据块
330	        // 1. 计算 hin
331	        // 2. 计算 h_post
332	        // 3. 计算 h_res
333	        globalOffsetM_ = offset * chunTSize_; // chunTSize_ = 192
334	
335	        if ASCEND_IS_AIV {
336	            V0VectorComputeProcess(offset, tBlockNum);
337	            AIV1Process(offset, tBlockNum);
338	            vec1Count_++;
339	        }
340	
341	        if ASCEND_IS_AIC {
342	            if (offset == tBlockNum - 1){
343	                mnConfig_.curSingleCoreM = totalLength_ - globalOffsetM_; // 尾块处理
344	            }
345	            AICProcess();
346	        }
347	    }
348	    if ASCEND_IS_AIV {
349	        invRmsOutQueue_.FreeTensor(invRmsUb_);
350	        biasInQue_.FreeTensor(biasInUb_);
351	    }
352	}
353	
354	template <class T, class P>
355	__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPreKernel<T, P>::AIV1GetHSliceOffset()
356	{
357	    uint32_t offset1 = 0;
358	    uint32_t offset2 = 0;
359	    uint32_t offset3 = 0;
360	    uint32_t curOffset = 0;
361	    uint32_t nSquare = N_ * N_;
362	    for (uint32_t i = 0; i < V1_BASE_T; i++) {
363	        for (uint32_t j = 0; j < N_; j++) {
364	            preOffsetBuf_.SetValue(offset1++, curOffset * sizeof(P));
365	            curOffset++;
366	        }
367	        for (uint32_t j = 0; j < N_; j++) {
368	            postOffsetBuf_.SetValue(offset2++, curOffset * sizeof(P));
369	            curOffset++;
370	        }
371	        for (uint32_t j = 0; j < nSquare; j++) {
372	            resOffsetBuf_.SetValue(offset3++, curOffset * sizeof(P));
373	            curOffset++;
374	        }
375	    }
376	}
377	template <class T, class P>
378	__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPreKernel<T, P>::AICProcess()
379	{
380	    uint64_t outOffset = 0;
381	    if (outFlag_) {
382	        outOffset = globalOffsetM_ * mnConfig_.n;
383	    } else {
384	        outOffset = mnConfig_.singleCoreM * mnConfig_.singleCoreN * ((mmCount_ % 2) * coreNum_ + coreIdx_);
385	    }
386	    mnConfig_.curSingleCoreK = mnConfig_.singleCoreK;
387	    for (uint64_t offsetNd = 0; offsetNd < mnConfig_.k; offsetNd += mnConfig_.singleCoreK)
388	    {
389	        AscendC::CrossCoreWaitFlag(SYNC_V2C);
390	        
391	        if(offsetNd + mnConfig_.singleCoreK > mnConfig_.k){
392	            mnConfig_.curSingleCoreK = mnConfig_.k - offsetNd;
393	        }
394	
395	        uint64_t xOffset = chunTSize_ * ND_LENGTH * (coreIdx_ + (cubeCount_ % parallNum_) * coreNum_);
396	
397	        mm.SetOrgShape(mnConfig_.curSingleCoreM, mnConfig_.curSingleCoreN, mnConfig_.curSingleCoreK,
398	                       mnConfig_.k); // MNK
399	        mm.SetSingleShape(mnConfig_.curSingleCoreM, mnConfig_.curSingleCoreN,
400	                          mnConfig_.curSingleCoreK); // SingleCoreMNK
401	        mm.SetTensorA(xFloatGm_[xOffset]);
402	        mm.SetTensorB(phiGm_[offsetNd], true);
403	        mm.IterateAll(mmResGm_[outOffset], offsetNd == 0 ? 0 : 1);
404	        mm.End();
405	        cubeCount_++;
406	        CrossCoreSetFlag<0x2, PIPE_FIX>(SYNC_C2V);
407	    }
408	    mmCount_++;
409	    CrossCoreSetFlag<0x2, PIPE_FIX>(SYNC_C2V1);
410	}
