412	template <class T, class P>
413	__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPreKernel<T, P>::VectorComputeOffset()
414	{
415	    uint64_t aliginSingleM = Ceil(curSingleM_ / 2, 8) * 8; // 32Byte对齐
416	    vectorOffset_.singleCoreM = aliginSingleM <  curSingleM_ ? aliginSingleM : curSingleM_;
417	    if (subBlockIdx_ == 0) {
418	        vectorOffset_.offsetMStart = 0;
419	        vectorOffset_.offsetMEnd = vectorOffset_.singleCoreM;
420	    } else {
421	        vectorOffset_.offsetMStart = vectorOffset_.singleCoreM;
422	        vectorOffset_.singleCoreM = curSingleM_ - vectorOffset_.singleCoreM;
423	        vectorOffset_.offsetMEnd = curSingleM_;
424	    }
425	}
