427	template <class T, class P>
428	__aicore__ inline void
429	AiInfraManifoldConstrainedHyperConnectionPreKernel<T, P>::V0VectorComputeProcess(uint32_t curblock, uint32_t tBlockNum)
430	{
431	    curSingleM_= chunTSize_;
432	    if (curblock == tBlockNum - 1) {
433	        curSingleM_= matrixInfo_.totalLength - curblock * chunTSize_;
434	    }
435	    VectorComputeOffset(); // 计算0核和1核的偏移
436	
437	    uint32_t computeLen = V0_BASE_T * ND_LENGTH;
438	    for (uint32_t offsetNd = 0; offsetNd < matrixInfo_.nD; offsetNd += ND_LENGTH) {
439	    
440	        uint32_t curNdLen = ND_LENGTH;
441	        if (offsetNd + ND_LENGTH >= matrixInfo_.nD) {
442	            curNdLen = matrixInfo_.nD - offsetNd;
443	        }
444	        if (vectorCount_ >= 2) {
445	            AscendC::CrossCoreWaitFlag(SYNC_C2V); // 等待cube
446	        }
447	        for (uint32_t offsetM = vectorOffset_.offsetMStart; offsetM < vectorOffset_.offsetMEnd; offsetM += V0_BASE_T) {
448	            uint32_t curMLen = V0_BASE_T;
449	            if (offsetM + V0_BASE_T >= vectorOffset_.offsetMEnd) {
450	                curMLen = vectorOffset_.offsetMEnd - offsetM;
451	            }
452	            uint64_t invRmsOffset = offsetM - vectorOffset_.offsetMStart;
453	            LocalTensor<P> invRmsUb = invRmsUb_[invRmsOffset];
454	            computeLen = curMLen * Ceil(curNdLen, 16) * 16;
455	            // copy x
456	            xLocal_ = xInQueue_.AllocTensor<T>();
457	            DataCopyX(curMLen, curNdLen, offsetM, offsetNd);
458	            xLocal_ = xInQueue_.DeQue<T>();
459	
460	            // bf16转fp32
461	            xFp32Ub_ = outQueue_.AllocTensor<P>();
462	            Cast(xFp32Ub_, xLocal_, AscendC::RoundMode::CAST_NONE, computeLen);
463	            // xFp32Ub_ * xFp32Ub_
464	            PipeBarrier<PIPE_V>();
465	            Mul(mulFp32Ub_, xFp32Ub_, xFp32Ub_, computeLen);
466	
467	            if (hasGamma_) {
468	                gammaUb_ = gammaInQueue_.AllocTensor<P>();
469	                DataCopyGamma(curNdLen, offsetNd);
470	                gammaUb_ = gammaInQueue_.DeQue<P>();
471	
472	                uint32_t broadCastDst[2] = {curMLen, curNdLen};
473	                uint32_t broadCastSrc[2] = {1, curNdLen};
474	                Broadcast<P, 2, 0>(gammaXFp32Ub_, gammaUb_, broadCastDst, broadCastSrc);
475	                PipeBarrier<PIPE_V>();
476	                Mul(xFp32Ub_, xFp32Ub_, gammaXFp32Ub_, computeLen);
477	                gammaInQueue_.FreeTensor(gammaUb_);
478	            }
479	
480	            PipeBarrier<PIPE_V>();
481	            DataCopyOutToWorkSpace(curMLen, curNdLen, offsetM, offsetNd);
482	            PipeBarrier<PIPE_V>();
483	            uint32_t srcShape[2] = {curMLen, Ceil(curNdLen, 16) * 16};
484	            if (offsetNd == 0) {
485	                ReduceSum<float, AscendC::Pattern::Reduce::AR, true>(invRmsUb, mulFp32Ub_, srcShape, true);
486	            } else {
487	                ReduceSum<float, AscendC::Pattern::Reduce::AR, true>(sumFp32Ub_, mulFp32Ub_, srcShape, true);
488	                PipeBarrier<PIPE_V>();
489	                Add(invRmsUb, invRmsUb, sumFp32Ub_, curMLen);
490	            }
491	            xInQueue_.FreeTensor(xLocal_);
492	            outQueue_.FreeTensor(xFp32Ub_);
493	        }
494	        CrossCoreSetFlag<0x2, PIPE_MTE3>(SYNC_V2C);
495	        vectorCount_++;
496	    }
497	
498	    PipeBarrier<PIPE_V>();
499	    Muls(invRmsUb_, invRmsUb_, scaleMean_, vectorOffset_.singleCoreM);
500	    PipeBarrier<PIPE_V>();
501	
502	    Adds(invRmsUb_, invRmsUb_, matrixInfo_.normEps, vectorOffset_.singleCoreM);
503	    PipeBarrier<PIPE_V>();
504	
505	    Sqrt(invRmsUb_, invRmsUb_, vectorOffset_.singleCoreM);
506	    PipeBarrier<PIPE_V>();
507	    Div(invRmsUb_, oneUb_, invRmsUb_, vectorOffset_.singleCoreM);
508	    PipeBarrier<PIPE_V>();
509	
510	    DataCopyOutInvRmsUb(vectorOffset_.singleCoreM, vectorOffset_.offsetMStart);
511	}
512	
513	template <class T, class P>
514	__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPreKernel<T, P>::AIV1Process(uint64_t curBlock,
515	                                                                                             uint64_t tBlockNum)
516	{
517	    curSingleM_= chunTSize_;
518	    if (curBlock == tBlockNum - 1) {
519	        curSingleM_= matrixInfo_.totalLength - curBlock * chunTSize_;
520	    }
521	    VectorComputeOffset(); // 计算0核和1核的偏移
522	    if (vectorOffset_.singleCoreM <= 0) {
523	        return;
524	    }
525	    AscendC::CrossCoreWaitFlag(SYNC_C2V1);
526	    uint64_t lenT = 0;
527	    uint64_t lenD = 0;
528	    uint64_t singleCoreOffset = 0;
529	    for (int offsetT = vectorOffset_.offsetMStart; offsetT < vectorOffset_.offsetMEnd; offsetT += V1_BASE_T) {
530	        lenT = V1_BASE_T < vectorOffset_.offsetMEnd - offsetT ? V1_BASE_T : vectorOffset_.offsetMEnd - offsetT;
531	        lenD = v1ChunkDSize_;
532	        // H 切分
533	        AIV1Prologue(offsetT, lenT, singleCoreOffset);
534	        AIV1ProcessHPost(offsetT, lenT, lenD);
535	        AIV1ProcessHPre(offsetT, lenT);
536	        auto hInDealBuf = inputBuff_; // 最大80K
537	        auto reduceResult = hInDealBuf[lenD * N_]; // 最大10K
538	        PipeBarrier<PIPE_ALL>();
539	
540	        for (uint32_t tIdx = 0; tIdx < lenT; tIdx++) {
541	            for (int offsetD = 0; offsetD < D_; offsetD += v1ChunkDSize_) {
542	                lenD = v1ChunkDSize_ < D_ - offsetD ? v1ChunkDSize_ : D_ - offsetD;
543	
544	   
545	                uint32_t ubOffset = 0;
546	                const uint32_t srcReduceShape_[2] = {static_cast<uint32_t>(N_), static_cast<uint32_t>(lenD)};
547	                for (uint32_t nIdx = 0; nIdx < N_; nIdx++) {
548	                    uint64_t xGmOffset = (globalOffsetM_ + offsetT + tIdx) * N_ * D_ + nIdx * D_ + offsetD;
549	
550	                    LocalTensor<T> xIn = xInQueue_.AllocTensor<T>();
551	                    // copy X
552	                    DataCopyExtParams copyParams;
553	                    copyParams.blockCount = static_cast<uint16_t>(1);
554	                    copyParams.blockLen = uint32_t(lenD * sizeof(T));
555	                    copyParams.srcStride = 0;
556	                    copyParams.dstStride = 0;
557	
558	                    uint32_t rightPadNum = Ceil(lenD, 16) * 16 - lenD;
559	                    DataCopyPadExtParams<T> padParams{true, 0, static_cast<uint8_t>(rightPadNum), 0};
560	                    DataCopyPad(xIn, xGm_[xGmOffset], copyParams, padParams);
561	
562	                    xInQueue_.EnQue(xIn);
563	                    xIn = xInQueue_.DeQue<T>();
564	
565	                    Cast(hInDealBuf[ubOffset], xIn, RoundMode::CAST_NONE, lenD);
566	                    PipeBarrier<PIPE_V>();
567	                    xInQueue_.FreeTensor(xIn);
568	
569	                    Muls(hInDealBuf[ubOffset], hInDealBuf[ubOffset], hPreBuff_.GetValue(tIdx * N_ + nIdx), lenD );
570	                    PipeBarrier<PIPE_V>();
571	                    ubOffset += lenD;
572	                }
573	
574	                // reducesum 
575	                ReduceSum<P, Pattern::Reduce::RA, true>(reduceResult, hInDealBuf, srcReduceShape_, true);
576	                PipeBarrier<PIPE_V>();
577	
578	                // cast
579	                LocalTensor<T> hinOut = outQueue_.AllocTensor<T>();
580	                Cast(hinOut, reduceResult, RoundMode::CAST_RINT, lenD);
581	                PipeBarrier<PIPE_V>();
582	    
583	                outQueue_.EnQue(hinOut);
584	                hinOut = outQueue_.DeQue<T>();
585	                // copyout
586	                DataCopyExtParams copyParams;
587	                copyParams.blockCount = 1; // 行数
588	                copyParams.blockLen = uint32_t(lenD * sizeof(T));
589	                copyParams.srcStride = 0;
590	                copyParams.dstStride = 0;
591	
592	                DataCopyPad(hinGm_[(globalOffsetM_ + offsetT + tIdx) * D_ + offsetD], hinOut, copyParams);
593	                PipeBarrier<PIPE_V>();
594	                outQueue_.FreeTensor(hinOut);
595	            }
596	        }
597	
598	        singleCoreOffset += V1_BASE_T;
599	    }
600	}
