602	template <class T, class P>
603	__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPreKernel<T, P>::AIV1Prologue(uint64_t offsetT,
604	                                                                                              uint64_t lenT,
605	                                                                                              uint64_t singleCoreOffset)
606	{
607	    uint64_t offset = globalOffsetM_ + offsetT;
608	    uint64_t HMixOffset = 0;
609	    LocalTensor<P> hResOutLocal = outQueue_.AllocTensor<P>();
610	    if (outFlag_) {
611	        HMixOffset = (globalOffsetM_ + offsetT) * mnConfig_.n;
612	    } else {
613	        HMixOffset = mnConfig_.singleCoreM * mnConfig_.singleCoreN * ((vec1Count_ % 2) * coreNum_ + coreIdx_) +
614	                     offsetT * mnConfig_.n; // 2: workspace开启2倍内存
615	    }
616	    HMixCopyIn(HMixOffset, lenT);
617	
618	    uint32_t hMixShape[] = {uint32_t(lenT), uint32_t(mnConfig_.n)};
619	    uint32_t alphaBiaShape[] = {uint32_t(1), uint32_t(mnConfig_.n)};
620	    uint32_t rShape[] = {uint32_t(lenT), uint32_t(1)};
621	    matmulRes_ = xInQueue_.DeQue<P>();
622	    Broadcast<P, 2, 1>(broadCastTmpUb_, invRmsUb_[singleCoreOffset], hMixShape, rShape);
623	    pipe_barrier(PIPE_V);
624	    matmulRes_ = matmulRes_ * broadCastTmpUb_;
625	    pipe_barrier(PIPE_V);
626	    Broadcast<P, 2, 0>(broadCastTmpUb_, alphaInUb_, hMixShape, alphaBiaShape);
627	    pipe_barrier(PIPE_V);
628	    matmulRes_ = matmulRes_ * broadCastTmpUb_;
629	    pipe_barrier(PIPE_V);
630	    Broadcast<P, 2, 0>(broadCastTmpUb_, biasInUb_, hMixShape, alphaBiaShape);
631	    pipe_barrier(PIPE_V);
632	    matmulRes_ = matmulRes_ + broadCastTmpUb_;
633	    pipe_barrier(PIPE_V);
634	
635	    SetFlag<HardEvent::MTE2_V>(EVENT_ID1);
636	    WaitFlag<HardEvent::MTE2_V>(EVENT_ID1);
637	
638	    Gather(hPreBuff_, matmulRes_, preOffsetBuf_, uint32_t(0), lenT * N_);
639	    Gather(hPostBuff_, matmulRes_, postOffsetBuf_, uint32_t(0), lenT * N_);
640	    Gather(hResOutLocal, matmulRes_, resOffsetBuf_, uint32_t(0), lenT * N_ * N_);
641	    PipeBarrier<PIPE_V>();
642	    outQueue_.EnQue(hResOutLocal);
643	    hResOutLocal = outQueue_.DeQue<P>();
644	    DataCopyExtParams copyParams;
645	    copyParams.blockCount = static_cast<uint16_t>(1);
646	    copyParams.blockLen = uint32_t(lenT * N_ * N_ * sizeof(P));
647	    copyParams.srcStride = uint32_t(0);
648	    copyParams.dstStride = uint32_t(0);
649	    DataCopyPad(hResGm_[offset * N_ * N_], hResOutLocal, copyParams);
650	    outQueue_.FreeTensor(hResOutLocal);
651	    xInQueue_.FreeTensor(matmulRes_);
652	}
