654	template <class T, class P>
655	__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPreKernel<T, P>::AIV1ProcessHPre(uint64_t offsetT,
656	                                                                                                 uint64_t lenT)
657	{
658	    uint64_t offset = globalOffsetM_ + offsetT;
659	    LocalTensor<P> hPreSigmoid = inputBuff_;
660	
661	    Sigmoid(hPreSigmoid, hPreBuff_, lenT * N_);
662	    PipeBarrier<PIPE_V>();
663	    Adds(hPreBuff_, hPreSigmoid, matrixInfo_.hcEps, lenT * N_);
664	    PipeBarrier<PIPE_V>();
665	    if (outFlag_){
666	        DataCopyExtParams copyParams;
667	        copyParams.blockCount = static_cast<uint16_t>(1); // 行数
668	        copyParams.blockLen = uint32_t(lenT * N_ * sizeof(P));
669	        copyParams.srcStride = uint32_t(0);
670	        copyParams.dstStride = uint32_t((0));
671	        SetFlag<HardEvent::V_MTE3>(EVENT_ID2);
672	        WaitFlag<HardEvent::V_MTE3>(EVENT_ID2);
673	        DataCopyPad(hPreGm_[offset * N_], hPreBuff_, copyParams);
674	    }
675	}
