677	template <class T, class P>
678	__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPreKernel<T, P>::AIV1ProcessHPost(uint64_t offsetT,
679	                                                                                                  uint64_t lenT,
680	                                                                                                  uint64_t lenD)
681	{
682	    uint64_t offset = globalOffsetM_ + offsetT;
683	    LocalTensor<P> hPostSigmoid = broadCastTmpUb_;
684	    LocalTensor<P> hPostOutLocal = outQueue_.AllocTensor<P>();
685	    Sigmoid(hPostSigmoid, hPostBuff_);
686	    PipeBarrier<PIPE_V>();
687	    Muls(hPostOutLocal, hPostSigmoid, static_cast<float>(2.0), lenT * N_);
688	    PipeBarrier<PIPE_V>();
689	    outQueue_.EnQue(hPostOutLocal);
690	    hPostOutLocal = outQueue_.DeQue<P>();
691	    DataCopyExtParams copyParams;
692	    copyParams.blockCount = static_cast<uint16_t>(1);
693	    copyParams.blockLen = uint32_t(lenT * N_ * sizeof(P));
694	    copyParams.srcStride = uint32_t(0);
695	    copyParams.dstStride = uint32_t(0);
696	    DataCopyPad(hPostGm_[offset * N_], hPostOutLocal, copyParams);
697	    outQueue_.FreeTensor(hPostOutLocal);
698	}
