700	template <class T, class P>
701	__aicore__ inline void AiInfraManifoldConstrainedHyperConnectionPreKernel<T, P>::AIVPreLoad()
702	{
703	    invRmsUb_ = invRmsOutQueue_.AllocTensor<P>();
704	    AIV1GetHSliceOffset();
705	
706	    float alphaPre = alphaGm_.GetValue(0);
707	    float alphaPost = alphaGm_.GetValue(1);
708	    float alphaComb = alphaGm_.GetValue(2);
709	    for(uint64_t i = 0; i < N_; ++i){
710	        alphaInUb_.SetValue(i, alphaPre);
711	        alphaInUb_.SetValue(i + N_, alphaPost);
712	        for(uint64_t j = 0; j < N_; ++j){
713	            alphaInUb_.SetValue((2 + i) * N_ + j, alphaComb);
714	        }
715	    }
716	    BiasCopyIn();
717	    biasInUb_ = biasInQue_.DeQue<P>();
718	}
