725	    DataCopyExtParams copyParams;
726	    copyParams.blockCount = static_cast<uint16_t>(1); // 行数
727	    copyParams.blockLen = uint32_t(matrixInfo_.fusionSize * sizeof(P));
728	    copyParams.srcStride = uint32_t(0); // 相邻块的间隔
729	    copyParams.dstStride = uint32_t(0);                                                   // 相邻块的间隔
730	    DataCopyPadExtParams<P> copyPadParams{true, 0, 0, 0};
731	
732	    DataCopyPad(biasLocal, biasGm_, copyParams, copyPadParams);
