48	ge::graphStatus AiInfraManifoldConstrainedHyperConnectionPreBaseTiling::GetInputShape()
49	{
50	    auto xTensor = context_->GetDynamicInputTensor(X_INDEX, 0);
51	    OP_CHECK_NULL_WITH_CONTEXT(context_, xTensor);
52	    auto phiTensor = context_->GetDynamicInputTensor(PHI_INDEX, 0);
53	    OP_CHECK_NULL_WITH_CONTEXT(context_, phiTensor);
54	    auto alphaTensor = context_->GetDynamicInputTensor(ALPHA_INDEX, 0);
55	    OP_CHECK_NULL_WITH_CONTEXT(context_, alphaTensor);
56	    auto biasTensor = context_->GetDynamicInputTensor(BIAS_INDEX, 0);
57	    OP_CHECK_NULL_WITH_CONTEXT(context_, biasTensor);
58	    auto gammaTensor = context_->GetDynamicInputTensor(GAMMA_INDEX, 0);
59	    if (gammaTensor == nullptr) {
60	        hasGamma_ = 0;
61	    } else {
62	        hasGamma_ = 1;
63	    }
64	    auto xDims = xTensor->GetStorageShape().GetDimNum();
65	    auto phiDims = phiTensor->GetStorageShape().GetDimNum();
66	    if (xDims == BSND_DIM_NUM) {
67	        // BSND格式: [B, S, N, D]
68	        uint64_t batch = xTensor->GetStorageShape().GetDim(INDEX_B_BSND);
69	        uint64_t sequence = xTensor->GetStorageShape().GetDim(INDEX_S_BSND);
70	        uint64_t numsResidual = xTensor->GetStorageShape().GetDim(INDEX_N_BSND);
71	        uint64_t dimens = xTensor->GetStorageShape().GetDim(INDEX_D_BSND);
72	        totalLength_ = batch * sequence;
73	        matK_ = numsResidual * dimens;
74	        N_ = numsResidual;
75	        D_ = dimens;
76	    } else if (xDims == TND_DIM_NUM) {
77	        // TND格式: [T, N, D]
78	        totalLength_ = xTensor->GetStorageShape().GetDim(INDEX_T_TND);
79	        uint64_t numsResidual = xTensor->GetStorageShape().GetDim(INDEX_N_TND);
80	        uint64_t dimens = xTensor->GetStorageShape().GetDim(INDEX_D_TND);
81	        matK_ = numsResidual * dimens;
82	        N_ = numsResidual;
83	        D_ = dimens;
84	    } else {
85	        OP_LOGE(context_->GetNodeName(), "xDims[%u] is invalid", xDims);
86	        return ge::GRAPH_FAILED;
87	    }
88	
89	    if (phiDims < 2) { // 2:phi的维度不小于2
90	        OP_LOGE(context_->GetNodeName(), "phiDims [%u] is invalid", phiDims);
91	        return ge::GRAPH_FAILED;
92	    }
93	
94	    static const std::vector<uint64_t> legalN = {4, 6, 8};
95	    if (std::find(legalN.begin(), legalN.end(), N_) == legalN.end()) {
96	        OP_LOGE(context_->GetNodeName(), "Invalid input shape N=%lu. Expected one of {4,6,8}", N_);
97	        return ge::GRAPH_FAILED;
98	    }
99	
100	    if (D_ % 16 != 0) { // 16 : D需要16对齐
101	        OP_LOGE(context_->GetNodeName(), "Invalid input shape D=%lu. Expected D to be 16-aligned", D_);
102	        return ge::GRAPH_FAILED;
103	    }
104	
105	    if (N_ * D_ > 65535) { // 65535 : n * D 需小于等于65535
106	        OP_LOGE(context_->GetNodeName(), "Invalid input shape nD=%lu. Expected n * D to be less than 65536", N_ * D_);
107	        return ge::GRAPH_FAILED;
108	    }
109	
110	    matM_ = totalLength_;
111	    matN_ = phiTensor->GetStorageShape().GetDim(0);  // phi的第二个维度是nD
112	
113	    if (N_ == 4) { // 4: n=4 时
114	        v1ChunkDSize_ = 5120; // n = 4 时，D维度切分大小为 5120.
115	    } else {
116	        v1ChunkDSize_ = 2560; // n = 6 或 8 时，D维度切分大小为 2560.
117	    }
118	
119	    // 检查phi的第二个维度是否等于matK_（即nD）
120	    uint64_t phiSecondDim = phiTensor->GetStorageShape().GetDim(1);
121	    if (phiSecondDim != matK_) {
122	        OP_LOGE(context_->GetNodeName(), "phi[1]=%u and matK_=%u (nD) shape is not compatible", phiSecondDim, matK_);
123	        return ge::GRAPH_FAILED;
124	    }
125	
126	    return ge::GRAPH_SUCCESS;
127	}
