129	ge::graphStatus AiInfraManifoldConstrainedHyperConnectionPreBaseTiling::ParseInputAndAttr()
130	{
131	    uint64_t ubSize = 0; 
132	    uint64_t l1Size = 0;
133	    uint64_t l0CSize = 0;
134	
135	    if (GetInputShape() != ge::GRAPH_SUCCESS) {
136	        OP_LOGE(context_->GetNodeName(), "get input shape failed");
137	        return ge::GRAPH_FAILED;
138	    }
139	
140	    auto platformInfo = context_->GetPlatformInfo();
141	    if (platformInfo == nullptr) {
142	        OP_LOGE(context_->GetNodeName(), "get platform info failed");
143	        return ge::GRAPH_FAILED;
144	    }
145	
146	    auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfo);
147	    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
148	    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::L1, l1Size);
149	    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::L0_C, l0CSize);
150	    mm_.SetBufferSpace(l1Size, l0CSize, ubSize);
151	    uint32_t maxBlockDim = ascendcPlatform.GetCoreNumAic();
152	    
153	    auto attrs = context_->GetAttrs();
154	    auto outFlagPtr = attrs->GetAttrPointer<uint32_t>(0);
155	    if (outFlagPtr != nullptr) {
156	        outFlag_ = static_cast<uint32_t>(*outFlagPtr);
157	    } else {
158	        outFlag_ = 0U;
159	    }
160	 
161	    auto normEpsPtr = attrs->GetAttrPointer<float>(1);
162	    if (normEpsPtr != nullptr) {
163	        normEps_ = *normEpsPtr;
164	    } else {
165	        normEps_ = 1e-6;
166	    }
167	
168	    auto hcEpsPtr = attrs->GetAttrPointer<float>(2);
169	    if (hcEpsPtr != nullptr) {
170	        hcEps_ = *hcEpsPtr;
171	    } else {
172	        hcEps_ = 1e-6;
173	    }
174	
175	    // 判断需要执行的模式
176	    if (totalLength_ > 180 || hasGamma_ == 1 || outFlag_ == 1) { // BS大于180，hasGamma等于1，outFlag等于1时走大BS的模板
177	        blockDim_ = maxBlockDim;
178	        SPLIT_ND_MODE = 0U; // 大BS
179	    } else {
180	        SPLIT_ND_MODE = 1U; // 小BS
181	        if (totalLength_ >= 160) {                              // 160: BS大于160，启用20个核
182	            blockDim_ = 20 <= maxBlockDim ? 20 : maxBlockDim;
183	        } else if (totalLength_ >= 40 ) {                       // 40: BS大于40，启用16个核
184	            blockDim_ = 16 <= maxBlockDim ? 16 : maxBlockDim;
185	        } else {                                                // BS小于于40，启用8个核
186	            blockDim_ = 8 <= maxBlockDim ? 8 : maxBlockDim;
187	        }
188	    }
189	    chunkTSize_ =
190	        (((totalLength_ + blockDim_ - 1) / blockDim_) + CHUNKT_ALIGN_NUM - 1) / CHUNKT_ALIGN_NUM * CHUNKT_ALIGN_NUM;
191	    if (chunkTSize_ > MAX_CHUNKTSIZE) {
192	        chunkTSize_ = MAX_CHUNKTSIZE;
193	    }
194	
195	    return ge::GRAPH_SUCCESS;
196	}
