199	void AiInfraManifoldConstrainedHyperConnectionPreBaseTiling::FillTilingData()
200	{
201	    // 矩阵计算剩余部分
202	    tilingData_.matmulTiling.set_dbL0C(2);  // 2: 开启double buffer
203	    tilingData_.matmulTiling.set_dbL0A(2);  // 2: 开启double buffer
204	    tilingData_.matmulTiling.set_dbL0B(2);  // 2: 开启double buffer
205	    tilingData_.matmulTiling.set_stepKa(1); 
206	    tilingData_.matmulTiling.set_stepKb(1);
207	    tilingData_.matmulTiling.set_depthA1(2);  // 2: stepKa的两倍，开启double buffer
208	    tilingData_.matmulTiling.set_depthB1(2);  // 2: stepKb的两倍，开启double buffer
209	    tilingData_.matmulTiling.set_stepM(1);
210	    tilingData_.matmulTiling.set_stepN(1);
211	
212	    uint32_t baseN = (matN_ + 16 - 1) / 16 * 16;  // 16: BaseM，16个元素对齐
213	    uint32_t baseK = 8 * 1024 / baseN / 8 * 8;  // 8 * 1024: 64k(L0Bsize) / 2(dbL0B) / 4(float), A矩阵不转置且
214	                                                // B矩阵转置场景下baseK以C0_size对齐，float场景下为8
215	    uint32_t baseM = 8 * 1024 / baseK / 16 * 16;  // 8 * 1024: 64k(L0Bsize) / 2(dbL0A) / 4(float), 16: BaseM，16个元素对齐
216	
217	    tilingData_.matmulTiling.set_baseM(baseM);
218	    tilingData_.matmulTiling.set_baseN(baseN);
219	    tilingData_.matmulTiling.set_baseK(baseK);
220	
221	    tilingData_.set_coreNum(blockDim_);
222	    tilingData_.set_totalLength(totalLength_);
223	    tilingData_.set_nD(matK_);
224	    tilingData_.set_fusionSize(matN_);
225	    tilingData_.set_N(N_);
226	    tilingData_.set_D(D_);
227	    tilingData_.set_normEps(normEps_);
228	    tilingData_.set_hcEps(hcEps_);
229	    tilingData_.set_chunkTSize(chunkTSize_);
230	    tilingData_.set_v1ChunkDSize(v1ChunkDSize_);
231	    tilingData_.set_outFlag(outFlag_);
232	    tilingData_.set_hasGamma(hasGamma_);
233	
234	    float scaleMean = 1.0f / static_cast<float>(matK_);
235	    tilingData_.set_scaleMean(scaleMean);
236	}
