238	ge::graphStatus AiInfraManifoldConstrainedHyperConnectionPreBaseTiling::TilingProcess()
239	{
240	    // 当前最大为128*128的matmul计算, 预留3倍空间适配最大矩阵
241	    // 2: workspace开启2倍空间。192：singleM的最大值。256：singleN的最大值。8：n的最大值
242	    size_t userWorkspaceSize = (2 * 192 * 256 +  2 * 192 * (8 * 8 + 2 * 8))* sizeof(float) * blockDim_;
243	    const size_t systemWorkspaceSize = static_cast<size_t>(20971520); // 20M
244	
245	    mm_.SetAType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT, false);
246	    mm_.SetBType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT, true);
247	    mm_.SetCType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT);
248	    mm_.SetBias(false);
249	    mm_.SetDim(1);
250	    mm_.SetShape(matM_, matN_, matK_);       
251	    mm_.SetOrgShape(matM_, matN_, matK_);    // 原始MNK
252	    if (mm_.GetTiling(tilingData_.matmulTiling) == -1) {
253	        OP_LOGE(context_->GetNodeName(),
254	                "AiInfraManifoldConstrainedHyperConnectionPreBaseTiling Get Tiling Failed!, batch, m: %lu, %lu",
255	                totalLength_, matM_);
256	        return ge::GRAPH_FAILED;
257	    }
258	
