86	        uint64_t numsResidual = xShape->GetDim(INDEX_N_BSND);
87	        uint64_t dimen = xShape->GetDim(IEDEX_D_BSND);
88	
89	        outHinShape->SetDimNum(BSND_DIM_NUM - 1); // 1 : outHinShape比xShapeDim少1维
90	        outHinShape->SetDim(INDEX_DIM_0, batch);
91	        outHinShape->SetDim(INDEX_DIM_1, sequence);
92	        outHinShape->SetDim(INDEX_DIM_2, dimen);
