95	        outHpostShape->SetDim(INDEX_DIM_0, batch);
96	        outHpostShape->SetDim(INDEX_DIM_1, sequence);
97	        outHpostShape->SetDim(INDEX_DIM_2, numsResidual);
98	
99	        outHresShape->SetDimNum(BSND_DIM_NUM);
100	        outHresShape->SetDim(INDEX_DIM_0, batch);
101	        outHresShape->SetDim(INDEX_DIM_1, sequence);
102	        outHresShape->SetDim(INDEX_DIM_2, numsResidual);
103	        outHresShape->SetDim(INDEX_DIM_3, numsResidual);
104	
105	        outInvRmsShape->SetDimNum(BSND_DIM_NUM - 2); // 2 : outInvRmsShape比xShapeDim小2维
106	        outInvRmsShape->SetDim(INDEX_DIM_0, batch);
107	        outInvRmsShape->SetDim(INDEX_DIM_1, sequence);
108	
109	        outMmresShape->SetDimNum(BSND_DIM_NUM - 1); // 1 : outMmresShape比xShapeDim小1维
110	        outMmresShape->SetDim(INDEX_DIM_0, batch);
111	        outMmresShape->SetDim(INDEX_DIM_1, sequence);
112	        outMmresShape->SetDim(INDEX_DIM_2, matK);
113	
114	        outHpreShape->SetDimNum(BSND_DIM_NUM - 1); // 1 : outHpreShape比xShapeDim小1维
115	        outHpreShape->SetDim(INDEX_DIM_0, batch);
116	        outHpreShape->SetDim(INDEX_DIM_1, sequence);
117	        outHpreShape->SetDim(INDEX_DIM_2, numsResidual);
118	    } else if (xShapeDim == TND_DIM_NUM) {
119	        uint64_t t = xShape->GetDim(INDEX_T_TND);
120	        uint64_t numsResidual = xShape->GetDim(INDEX_N_TND);
