const constexpr int64_t X_INDEX = 0;
const constexpr int64_t PHI_INDEX = 1;

const constexpr int64_t OUT_H_IN_INDEX = 0;
const constexpr int64_t OUT_H_POST_INDEX = 1;
const constexpr int64_t OUT_H_RES_INDEX = 2;
const constexpr int64_t OUT_INV_RMS_INDEX = 3;
const constexpr int64_t OUT_MM_RES_INDEX = 4;
const constexpr int64_t OUT_H_PRE_INDEX = 5;

const constexpr int64_t BSND_DIM_NUM = 4;
const constexpr int64_t TND_DIM_NUM = 3;

const constexpr int64_t INDEX_B_BSND = 0;
const constexpr int64_t INDEX_S_BSND = 1;
const constexpr int64_t INDEX_N_BSND = 2;
const constexpr int64_t IEDEX_D_BSND = 3;

const constexpr int64_t INDEX_T_TND = 0;
const constexpr int64_t INDEX_N_TND = 1;
const constexpr int64_t INDEX_D_TND = 2;

const constexpr int64_t INDEX_DIM_0 = 0;
const constexpr int64_t INDEX_DIM_1 = 1;
const constexpr int64_t INDEX_DIM_2 = 2;
const constexpr int64_t INDEX_DIM_3 = 3;

static ge::graphStatus InferShape4mHCPre(InferShapeContext *context)
{
    OP_LOGD(context->GetNodeName(), "Begin to do InferShape AiInfraManifoldConstrainedHyperConnectionPre");
    const gert::Shape *xShape = context->GetDynamicInputShape(X_INDEX, 0);
        OP_CHECK_NULL_WITH_CONTEXT(context, xShape);
    const gert::Shape *phiShape = context->GetDynamicInputShape(PHI_INDEX, 0);
        OP_CHECK_NULL_WITH_CONTEXT(context, phiShape);

    int64_t xShapeDim = xShape->GetDimNum();
    int64_t phiShapeDim = xShape->GetDimNum();
    auto outHinShape = context->GetOutputShape(OUT_H_IN_INDEX);
    auto outHpostShape = context->GetOutputShape(OUT_H_POST_INDEX);
    auto outHresShape = context->GetOutputShape(OUT_H_RES_INDEX);

    auto outInvRmsShape = context->GetOutputShape(OUT_INV_RMS_INDEX);
    auto outMmresShape = context->GetOutputShape(OUT_MM_RES_INDEX);
    auto outHpreShape = context->GetOutputShape(OUT_H_PRE_INDEX);

    if (phiShapeDim < 2) { // 2 : phi维度不小于2
        OP_LOGD(context->GetNodeName(), "phiShapeDim dims is invalid");
        return GRAPH_FAILED;
    }

    uint64_t matK = phiShape->GetDim(0);
    if (xShapeDim == BSND_DIM_NUM) {
        uint64_t batch = xShape->GetDim(INDEX_B_BSND);
        uint64_t sequence = xShape->GetDim(INDEX_S_BSND);
        uint64_t numsResidual = xShape->GetDim(INDEX_N_BSND);
        uint64_t dimen = xShape->GetDim(IEDEX_D_BSND);

        outHinShape->SetDimNum(BSND_DIM_NUM - 1); // 1 : outHinShape比xShapeDim少1维
        outHinShape->SetDim(INDEX_DIM_0, batch);
        outHinShape->SetDim(INDEX_DIM_1, sequence);
        outHinShape->SetDim(INDEX_DIM_2, dimen);

        outHpostShape->SetDimNum(BSND_DIM_NUM - 1); // 1 : outHpostShape比xShapeDim少1维
        outHpostShape->SetDim(INDEX_DIM_0, batch);
        outHpostShape->SetDim(INDEX_DIM_1, sequence);
        outHpostShape->SetDim(INDEX_DIM_2, numsResidual);

        outHresShape->SetDimNum(BSND_DIM_NUM);
        outHresShape->SetDim(INDEX_DIM_0, batch);
        outHresShape->SetDim(INDEX_DIM_1, sequence);
        outHresShape->SetDim(INDEX_DIM_2, numsResidual);
        outHresShape->SetDim(INDEX_DIM_3, numsResidual);

        outInvRmsShape->SetDimNum(BSND_DIM_NUM - 2); // 2 : outInvRmsShape比xShapeDim小2维
        outInvRmsShape->SetDim(INDEX_DIM_0, batch);
        outInvRmsShape->SetDim(INDEX_DIM_1, sequence);

        outMmresShape->SetDimNum(BSND_DIM_NUM - 1); // 1 : outMmresShape比xShapeDim小1维
        outMmresShape->SetDim(INDEX_DIM_0, batch);
        outMmresShape->SetDim(INDEX_DIM_1, sequence);
        outMmresShape->SetDim(INDEX_DIM_2, matK);

        outHpreShape->SetDimNum(BSND_DIM_NUM - 1); // 1 : outHpreShape比xShapeDim小1维
        outHpreShape->SetDim(INDEX_DIM_0, batch);
        outHpreShape->SetDim(INDEX_DIM_1, sequence);
        outHpreShape->SetDim(INDEX_DIM_2, numsResidual);
    } else if (xShapeDim == TND_DIM_NUM) {
        uint64_t t = xShape->GetDim(INDEX_T_TND);
        uint64_t numsResidual = xShape->GetDim(INDEX_N_TND);
        uint64_t dimen = xShape->GetDim(INDEX_D_TND);

        outHinShape->SetDimNum(TND_DIM_NUM - 1);  // 1 : outHinShape比xShapeDim少1维
        outHinShape->SetDim(INDEX_DIM_0, t);
        outHinShape->SetDim(INDEX_DIM_1, dimen);

        outHpostShape->SetDimNum(TND_DIM_NUM - 1); // 1 : outHpostShape比xShapeDim少1维
        outHpostShape->SetDim(INDEX_DIM_0, t);
        outHpostShape->SetDim(INDEX_DIM_1, numsResidual);

        outHresShape->SetDimNum(TND_DIM_NUM);
        outHresShape->SetDim(INDEX_DIM_0, t);
        outHresShape->SetDim(INDEX_DIM_1, numsResidual);
        outHresShape->SetDim(INDEX_DIM_2, numsResidual);

        outInvRmsShape->SetDimNum(TND_DIM_NUM - 2); // 2 : outInvRmsShape比xShapeDim小2维
        outInvRmsShape->SetDim(INDEX_DIM_0, t);

        outMmresShape->SetDimNum(TND_DIM_NUM - 1); // 1 : outMmresShape比xShapeDim小1维
        outMmresShape->SetDim(INDEX_DIM_0, t);
        outMmresShape->SetDim(INDEX_DIM_1, matK);

        outHpreShape->SetDimNum(TND_DIM_NUM - 1); // 1 : outHpreShape比xShapeDim小1维
        outHpreShape->SetDim(INDEX_DIM_0, t);
        outHpreShape->SetDim(INDEX_DIM_1, numsResidual);
    } else {
        OP_LOGE(context->GetNodeName(), "xShapeDim dims is invalid");
        return GRAPH_FAILED;
    }

    OP_LOGD(context->GetNodeName(), "End to do InferShape AiInfraManifoldConstrainedHyperConnectionPre");
    return GRAPH_SUCCESS;
}

static graphStatus InferDataType4mHCPre(gert::InferDataTypeContext *context)
{
    context->SetOutputDataType(0, DataType::DT_FLOAT);
    context->SetOutputDataType(0, DataType::DT_FLOAT);
    context->SetOutputDataType(0, DataType::DT_FLOAT);
    return GRAPH_SUCCESS;
}

IMPL_OP_INFERSHAPE(AiInfraManifoldConstrainedHyperConnectionPre)
    .InferShape(InferShape4mHCPre)
    .InferDataType(InferDataType4mHCPre);
